  var DEMO_EMAIL_LIST = new Set(["admin@sagarsoft.com","teacher@sagarsoft.com","student@sagarsoft.com","parent@sagarsoft.com"]);
  var isDemoUser = currentUser && DEMO_EMAIL_LIST.has(String(currentUser.email || "").trim().toLowerCase());
  const roleRouteAllowMap = {
    superadmin: ["*"],
    admin: ["*"],
    teacher: [
      "dashboard",
      "all-students",
      "all-classes",
      "classes-with-subjects",
      "students-attendance",
      "students-attendance-report",
      "class-wise-report",
      "create-new-exam",
      "add-update-exam-marks",
      "result-card",
      "result-sheet",
      "exam-schedule",
      "date-sheet",
      "blank-award-list",
      "manage-test-marks",
      "test-result",
      "homework",
      "generate-for-class",
      "generate-for-teacher",
      "students-report-card",
      "students-info-report",
      "staff-monthly-attendance-report",
      "student-progress-report"
    ],
    student: [
      "dashboard",
      "students-attendance-report",
      "result-card",
      "test-result",
      "students-report-card",
      "student-progress-report",
      "homework"
    ],
    parent: [
      "dashboard",
      "students-report-card",
      "students-info-report",
      "fee-collection-report",
      "student-progress-report"
    ]
  };

  function getNormalizedStudentsDataset() {
    return (database.students || []).map(function (student) {
      return normalizeStudentForPrint(student);
    });
  }

  function normalizeStudentsDatasetInMemory() {
    database.students = getNormalizedStudentsDataset().map(function (student) {
      return {
        ...student,
        status: String(student.status || "").toLowerCase() === "inactive" ? "inactive" : "active"
      };
    });
  }

  function setClassMessage(message, type) {
    newClassFormMessage.textContent = message;
    newClassFormMessage.className = "form-message" + (type ? ` ${type}` : "");
  }

  function setAllClassesMessage(message, type) {
    allClassesMessage.textContent = message;
    allClassesMessage.className = "form-message" + (type ? ` ${type}` : "");
  }

  function setClassesWithSubjectsMessage(message, type) {
    classesWithSubjectsMessage.textContent = message;
    classesWithSubjectsMessage.className = "form-message" + (type ? ` ${type}` : "");
  }

  function setAssignSubjectsMessage(message, type) {
    assignSubjectsMessage.textContent = message;
    assignSubjectsMessage.className = "form-message" + (type ? ` ${type}` : "");
  }

  function refreshDatabase() {
    database = window.SagarSoftDB.getDatabase();
    normalizeStudentsDatasetInMemory();
    ensureLicenseSettings();
  }

  function applySavedThemeSettings() {
    const themeSettings = database.generalSettings && database.generalSettings.themeLanguage;
    if (!themeSettings) {
      return;
    }
    sidebar.style.background = themeSettings.sidebarBackground || "";
    document.querySelector(".topbar").style.background = themeSettings.headerBackground || "";
    document.documentElement.style.setProperty("--primary-color", themeSettings.activeItemBackground || "#1e5eff");
    document.documentElement.setAttribute("dir", themeSettings.placement === "RTL" ? "rtl" : "ltr");
  }

  function saveDatabase() {
    window.SagarSoftDB.saveDatabase(database);
  }

  function ensureLicenseSettings() {
    if (!database.generalSettings) {
      database.generalSettings = {};
    }
    if (!database.generalSettings.licenseSettings) {
      database.generalSettings.licenseSettings = {};
    }
    const profile = (database.generalSettings && database.generalSettings.instituteProfile) || {};
    const fallbackSchoolName = profile.name || database.school.name || "SagarSoft Public School";
    const license = database.generalSettings.licenseSettings;
    const accountSettings = database.generalSettings.accountSettings || {};
    const defaultLicense = {
      schoolId: "SCH-" + Date.now().toString(36).toUpperCase() + "-" + Math.random().toString(36).slice(2, 6).toUpperCase(),
      schoolName: fallbackSchoolName,
      activated: false,
      subscriptionPlan: "monthly",
      customDays: 30,
      startDate: "",
      expiryDate: "",
      status: "inactive",
      lastVerifiedAt: "",
      verificationIntervalDays: 9999,
      websiteEndpoint: (window.SagarSoftOnlineConfig && window.SagarSoftOnlineConfig.apiBaseUrl) || "https://sagarsoftonline.onrender.com",
      licenseToken: "",
      lastServerResponse: ""
    };
    database.generalSettings.licenseSettings = { ...defaultLicense, ...license };
    if (!database.generalSettings.licenseSettings.expiryDate && accountSettings.expiry) {
      database.generalSettings.licenseSettings.expiryDate = formatDateInput(accountSettings.expiry);
    }
    if (!database.generalSettings.licenseSettings.schoolName && accountSettings.schoolName) {
      database.generalSettings.licenseSettings.schoolName = String(accountSettings.schoolName || "").trim();
    }
    return database.generalSettings.licenseSettings;
  }

  function getPlanDays(plan, customDays) {
    if (plan === "monthly") { return 30; }
    if (plan === "3-months" || plan === "3months") { return 90; }
    if (plan === "5-months" || plan === "5months") { return 150; }
    if (plan === "1-year" || plan === "1year") { return 365; }
    const parsedDays = Number(customDays || 0);
    return parsedDays > 0 ? parsedDays : 30;
  }

  function formatDateInput(value) {
    const date = value ? new Date(value) : new Date();
    return Number.isNaN(date.getTime()) ? new Date().toISOString().slice(0, 10) : date.toISOString().slice(0, 10);
  }

  function parseFlexibleDate(value) {
    const raw = String(value || "").trim();
    if (!raw) {
      return null;
    }
    const dateFromNative = new Date(raw);
    if (!Number.isNaN(dateFromNative.getTime())) {
      return dateFromNative;
    }
    const ddmmyyyy = raw.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
    if (ddmmyyyy) {
      const day = Number(ddmmyyyy[1]);
      const month = Number(ddmmyyyy[2]) - 1;
      const year = Number(ddmmyyyy[3]);
      const parsed = new Date(year, month, day, 23, 59, 59, 999);
      if (!Number.isNaN(parsed.getTime())) {
        return parsed;
      }
    }
    return null;
  }

  function addDaysISO(startDate, days) {
    const date = new Date(startDate);
    if (Number.isNaN(date.getTime())) {
      return "";
    }
    date.setDate(date.getDate() + Math.max(1, Number(days || 0)));
    return date.toISOString().slice(0, 10);
  }

  function toBase64Unicode(input) {
    try {
      const bytes = new TextEncoder().encode(String(input || ""));
      let binary = "";
      const chunkSize = 0x8000;
      for (let index = 0; index < bytes.length; index += chunkSize) {
        const chunk = bytes.subarray(index, index + chunkSize);
        binary += String.fromCharCode.apply(null, Array.from(chunk));
      }
      return btoa(binary);
    } catch (error) {
      return "";
    }
  }

  function fromBase64Unicode(input) {
    try {
      const binary = atob(String(input || ""));
      const bytes = new Uint8Array(binary.length);
      for (let index = 0; index < binary.length; index += 1) {
        bytes[index] = binary.charCodeAt(index);
      }
      return new TextDecoder().decode(bytes);
    } catch (error) {
      return "";
    }
  }

  function simpleHash(input) {
    const text = String(input || "");
    let hash = 0;
    for (let index = 0; index < text.length; index += 1) {
      hash = ((hash << 5) - hash) + text.charCodeAt(index);
      hash |= 0;
    }
    return String(Math.abs(hash));
  }

  function getLicenseSigningSecret() {
    return "SAGARSOFT-OFFLINE-LICENSE-2026";
  }

  function generateOfflineLicenseToken(payload) {
    const body = {
      schoolId: String(payload.schoolId || "").trim(),
      schoolName: String(payload.schoolName || "").trim(),
      schoolEmail: String(payload.schoolEmail || "").trim().toLowerCase(),
      schoolPassword: String(payload.schoolPassword || "").trim(),
      activated: typeof payload.activated === "boolean" ? payload.activated : true,
      plan: String(payload.plan || "monthly"),
      startDate: formatDateInput(payload.startDate || new Date().toISOString().slice(0, 10)),
      expiryDate: formatDateInput(payload.expiryDate || new Date().toISOString().slice(0, 10)),
      issuedAt: new Date().toISOString()
    };
    const encoded = toBase64Unicode(JSON.stringify(body));
    const signature = simpleHash(`${encoded}|${getLicenseSigningSecret()}`);
    return `SSMS-KEY-${encoded}.${signature}`;
  }

  function parseOfflineLicenseToken(token) {
    const raw = String(token || "").trim();
    if (!raw.startsWith("SSMS-KEY-")) {
      return { ok: false, message: "Invalid license key format." };
    }
    const compact = raw.replace("SSMS-KEY-", "");
    const parts = compact.split(".");
    if (parts.length !== 2) {
      return { ok: false, message: "Corrupted license key." };
    }
    const encoded = parts[0];
    const signature = parts[1];
    const expected = simpleHash(`${encoded}|${getLicenseSigningSecret()}`);
    if (signature !== expected) {
      return { ok: false, message: "License key signature mismatch." };
    }
    const decoded = fromBase64Unicode(encoded);
    if (!decoded) {
      return { ok: false, message: "Unable to decode license key." };
    }
    let parsed = null;
    try {
      parsed = JSON.parse(decoded);
    } catch (error) {
      return { ok: false, message: "Invalid license payload." };
    }
    return { ok: true, data: parsed };
  }

  function isRouteAllowedByRole(route) {
    const allowList = roleRouteAllowMap[currentUser.role] || ["dashboard"];
    if (allowList.includes("*")) {
      return true;
    }
    return allowList.includes(route);
  }

  function getLicenseLockState() {
    const license = ensureLicenseSettings();
    if (superAdminBypass) {
      return { locked: false, reason: "" };
    }
    if (isDemoUser) {
      return { locked: false, reason: "" };
    }
    if (!license.activated) {
      return { locked: true, reason: "Account activation is required. Please contact Super Admin." };
    }
    if (String(license.status || "").toLowerCase() === "inactive") {
      return { locked: true, reason: "School account is inactive. Please contact Super Admin." };
    }
    const accountSettings = (database.generalSettings && database.generalSettings.accountSettings) || {};
    const expiryRaw = String(license.expiryDate || accountSettings.expiry || "").trim();
    const today = new Date();
    const expiry = parseFlexibleDate(expiryRaw);
    if (expiry && !Number.isNaN(expiry.getTime()) && today > expiry) {
      return { locked: true, reason: "Subscription has expired. Please renew from Super Admin panel." };
    }
    return { locked: false, reason: "" };
  }

  function isRouteLockedByLicense(route) {
    const licenseLock = getLicenseLockState();
    if (!licenseLock.locked) {
      return false;
    }
    const license = ensureLicenseSettings();
    const allowedDuringLock = license.activated ? ["account-settings"] : ["account-settings"];
    return !allowedDuringLock.includes(route);
  }

  function applyRouteAccessVisibility() {
    const licenseLock = getLicenseLockState();
    routeButtons.forEach(function (button) {
      const route = button.dataset.route;
      if (!route) {
        return;
      }
      const allowedByRole = isRouteAllowedByRole(route);
      const lockedByLicense = isRouteLockedByLicense(route);
      const allowed = allowedByRole && !lockedByLicense;
      button.style.display = allowed ? "" : "none";
      button.disabled = !allowed;
      if (lockedByLicense) {
        button.title = licenseLock.reason;
      } else if (!allowedByRole) {
        button.title = "This option is restricted for your role.";
      } else {
        button.title = "";
      }
    });
    if (licenseLock.locked && !superAdminBypass) {
      document.querySelectorAll('[data-route="account-settings"]').forEach(function (button) {
        button.style.display = "";
        button.disabled = false;
        button.title = "";
      });
      const generalSettingsTrigger = document.querySelector('[data-accordion="general-settings"]');
      const generalSettingsGroup = generalSettingsTrigger ? generalSettingsTrigger.closest(".menu-group") : null;
      if (generalSettingsGroup && generalSettingsTrigger) {
        generalSettingsGroup.classList.add("open");
        generalSettingsTrigger.setAttribute("aria-expanded", "true");
      }
    }
    document.querySelectorAll(".menu-group").forEach(function (group) {
      var visibleRoutes = group.querySelectorAll('.submenu-link[data-route]');
      var anyVisible = false;
      visibleRoutes.forEach(function (btn) {
        if (btn.style.display !== "none") anyVisible = true;
      });
      var accordionTrigger = group.querySelector('[data-accordion]');
      if (visibleRoutes.length > 0 && !anyVisible) {
        group.style.display = "none";
        if (accordionTrigger) accordionTrigger.style.display = "none";
      } else {
        group.style.display = "";
        if (accordionTrigger) accordionTrigger.style.display = "";
      }
    });
  }

  function normalizeLicenseEndpoint(value) {
    const defaultEndpoint = (window.SagarSoftOnlineConfig && window.SagarSoftOnlineConfig.apiBaseUrl) || "https://sagarsoftonline.onrender.com";
    let endpoint = String(value || defaultEndpoint).trim().replace(/\/+$/, "");
    if (!endpoint || endpoint.includes("infinityfreeapp.com")) {
      return defaultEndpoint;
    }
    endpoint = endpoint
      .replace(/\/backend-php\/api\.php$/i, "")
      .replace(/\/api\/activate-school\.php$/i, "")
      .replace(/\/api\/check-license\.php$/i, "")
      .replace(/\/api\/sync-school-data\.php$/i, "")
      .replace(/\/api$/i, "");
    return endpoint || defaultEndpoint;
  }

  function getOnlineDeviceId() {
    const key = "sagarsoft_device_id";
    try { return sessionStorage.getItem(key) || ""; } catch (e) { return ""; }
  }

  function normalizePortalPlan(plan) {
    const raw = String(plan || "monthly").toLowerCase();
    if (raw === "3months") { return "3-months"; }
    if (raw === "5months") { return "5-months"; }
    if (raw === "1year") { return "1-year"; }
    return raw || "monthly";
  }

  function mergePortalNotifications(rows) {
    ensurePortalSyncData();
    const incoming = Array.isArray(rows) ? rows : [];
    let added = 0;
    incoming.forEach(function (note) {
      const noteId = `PORTAL-${String(note.id || "")}`;
      if (!note.id || database.portalSync.appliedNotificationIds.includes(noteId)) {
        return;
      }
      database.notifications.unshift({
        id: noteId,
        title: note.title || "Portal Notification",
        message: note.message || "-",
        createdAt: note.created_at || new Date().toISOString(),
        read: false,
        source: "portal"
      });
      database.portalSync.appliedNotificationIds.push(noteId);
      added += 1;
    });
    if (added > 0) {
      database.notifications = database.notifications.slice(0, 100);
      renderNotificationList();
    }
    return added;
  }

  function applyOnlineLicensePayload(payload) {
    if (!payload || !payload.success) {
      return;
    }
    const license = ensureLicenseSettings();
    const accountSettings = database.generalSettings.accountSettings || {};
    license.schoolId = String(payload.school_id || license.schoolId || "").trim();
    license.schoolName = String(payload.school_name || license.schoolName || "").trim();
    license.activated = String(payload.activation_status || payload.status || "").toLowerCase() === "active" && !payload.modules_locked;
    license.subscriptionPlan = normalizePortalPlan(payload.plan || license.subscriptionPlan);
    license.startDate = formatDateInput(payload.start_date || license.startDate || new Date().toISOString().slice(0, 10));
    license.expiryDate = formatDateInput(payload.expiry_date || license.expiryDate || new Date().toISOString().slice(0, 10));
    license.status = String(payload.activation_status || payload.status || (license.activated ? "active" : "inactive")).toLowerCase();
    license.licenseToken = String(payload.license_token || license.licenseToken || "").trim();
    license.verificationIntervalDays = Number(payload.internet_required_after_days || license.verificationIntervalDays || 20);
    license.lastVerifiedAt = new Date().toISOString();
    license.lastServerResponse = JSON.stringify(payload);
    accountSettings.subscription = license.subscriptionPlan;
    accountSettings.expiry = license.expiryDate;
    if (payload.email) {
      accountSettings.username = String(payload.email || "").trim();
    }
    if (license.schoolName) {
      database.school.name = license.schoolName;
      if (database.generalSettings.instituteProfile) {
        database.generalSettings.instituteProfile.name = license.schoolName;
      }
    }
    mergePortalNotifications(payload.notifications || []);
  }

  async function postLicenseJson(url, body) {
    const response = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body)
    });
    const payload = await response.json().catch(function () { return {}; });
    if (!response.ok || !payload.success) {
      throw new Error(payload.message || `Server request failed (${response.status}).`);
    }
    return payload;
  }

  async function verifyLicenseWithServer(options) {
    const opts = options || {};
    const license = ensureLicenseSettings();
    const accountSettings = database.generalSettings.accountSettings || {};
    const baseUrl = (window.SagarSoftOnlineConfig && window.SagarSoftOnlineConfig.apiBaseUrl) || "https://sagarsoftonline.onrender.com";
    const endpoint = normalizeLicenseEndpoint(license.websiteEndpoint || baseUrl);
    let payload = null;

    if (opts.forceActivate) {
      var syncEmailInput = document.getElementById("accountUsernameInput");
      var syncPasswordInput = document.getElementById("accountPasswordInput");
      var syncEmail = syncEmailInput ? String(syncEmailInput.value).trim().toLowerCase() : "";
      var syncPassword = syncPasswordInput ? String(syncPasswordInput.value).trim() : "";
      if (!syncEmail || !syncPassword) {
        throw new Error("School email and password are required for online activation.");
      }
      payload = await postLicenseJson(`${endpoint}/api/sync-school-data.php`, {
        school_id: license.schoolId,
        school_name: license.schoolName,
        email: syncEmail,
        password: syncPassword,
        activation_status: "active",
        plan: String(license.subscriptionPlan || "monthly").replace("3-months", "3months").replace("5-months", "5months").replace("1-year", "1year"),
        start_date: license.startDate || new Date().toISOString().slice(0, 10),
        expiry_date: license.expiryDate || null,
        license_token: license.licenseToken || null,
        basic_data: {
          school_name: license.schoolName,
          total_students: (database.students || []).length,
          total_employees: (database.teachers || []).length,
          software_version: "1.0.0",
          last_seen: new Date().toISOString()
        }
      });
      if (payload && payload.license) {
        applyOnlineLicensePayload(payload.license);
      }
    } else if (!license.licenseToken) {
      var actEmailInput = document.getElementById("accountUsernameInput");
      var actPasswordInput = document.getElementById("accountPasswordInput");
      const email = actEmailInput ? String(actEmailInput.value).trim().toLowerCase() : "";
      const password = actPasswordInput ? String(actPasswordInput.value).trim() : "";
      if (!email || !password) {
        throw new Error("School email and password are required.");
      }
      payload = await postLicenseJson(`${endpoint}/api/activate-school.php`, {
        email: email,
        password: password,
        device_id: getOnlineDeviceId()
      });
      applyOnlineLicensePayload(payload);
    } else {
      payload = await postLicenseJson(`${endpoint}/api/check-license.php`, {
        school_id: license.schoolId,
        license_token: license.licenseToken
      });
      applyOnlineLicensePayload(payload);
    }

    const refreshedLicense = ensureLicenseSettings();
    try {
      var syncEmail2Input = document.getElementById("accountUsernameInput");
      var syncPassword2Input = document.getElementById("accountPasswordInput");
      var syncEmail2 = syncEmail2Input ? String(syncEmail2Input.value).trim().toLowerCase() : "";
      var syncPassword2 = syncPassword2Input ? String(syncPassword2Input.value).trim() : "";
      var syncPayload = null;
      if (!opts.forceActivate) {
        syncPayload = await postLicenseJson(`${endpoint}/api/sync-school-data.php`, {
          school_id: refreshedLicense.schoolId,
          license_token: refreshedLicense.licenseToken,
          school_name: refreshedLicense.schoolName,
          email: syncEmail2,
          password: syncPassword2,
          activation_status: String(refreshedLicense.status || (refreshedLicense.activated ? "active" : "inactive")).toLowerCase(),
          plan: String(refreshedLicense.subscriptionPlan || "monthly").replace("3-months", "3months").replace("5-months", "5months").replace("1-year", "1year"),
          start_date: refreshedLicense.startDate,
          expiry_date: refreshedLicense.expiryDate,
          basic_data: {
            school_name: refreshedLicense.schoolName,
            total_students: (database.students || []).length,
            total_employees: (database.teachers || []).length,
            software_version: "1.0.0",
            last_seen: new Date().toISOString()
          }
        });
      }
      if (syncPayload && syncPayload.license) {
        applyOnlineLicensePayload(syncPayload.license);
      }
    } catch (syncError) {
      // License check succeeded; keep the app usable even if optional sync fails.
    }

    saveDatabase();
    applyRouteAccessVisibility();
    renderNotificationList();
    return { success: true, message: "Online license verified successfully.", payload: payload };
  }

  function addActivity(title, description) {
    database.activityLogs.unshift({
      id: `ACT-${Date.now()}`,
      title: title,
      description: description,
      createdAt: new Date().toISOString()
    });
  }

  function getInitials(name) {
    const safeName = String(name || "").trim();
    if (!safeName) {
      return "NA";
    }
    return safeName
      .split(" ")
      .filter(Boolean)
      .slice(0, 2)
      .map(function (part) {
        return part.charAt(0).toUpperCase();
      })
      .join("");
  }

  function getRoleLabel(roleValue) {
    const value = String(roleValue || "").toLowerCase();
    if (value === "superadmin") {
      return "Super Admin";
    }
    return value ? value.charAt(0).toUpperCase() + value.slice(1) : "User";
  }

  function escapeHtml(value) {
    return String(value || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
  }

  function escapeAttr(value) {
    return escapeHtml(value).replace(/"/g, "&quot;");
  }

  function renderStudentSearchResult(student) {
    return `
      <div style="padding: 0.8rem 1rem; border-bottom: 1px solid rgba(27,95,122,0.1); cursor: pointer; display: grid; grid-template-columns: 1fr auto; gap: 1rem; align-items: center; transition: background 0.2s;" data-student-id="${escapeAttr(student.id || "")}" class="search-result-item">
        <div>
          <div style="font-weight: 600; color: #0f2b3f;">${escapeHtml(student.name || "-")}</div>
          <div style="font-size: 0.85rem; color: #888;">${escapeHtml(student.className || "-")}</div>
        </div>
        <div style="text-align: right; font-size: 0.85rem; color: #1b5f7a; font-weight: 600;">${escapeHtml(student.admissionNo || "-")}</div>
      </div>
    `;
  }

  function renderEmployeeSearchResult(employee) {
    return `
      <div style="padding: 0.8rem 1rem; border-bottom: 1px solid rgba(27,95,122,0.1); cursor: pointer; display: grid; grid-template-columns: 1fr auto; gap: 1rem; align-items: center; transition: background 0.2s;" data-item='${JSON.stringify(employee)}' class="search-result-item">
        <div>
          <div style="font-weight: 600; color: #0f2b3f;">${escapeHtml(employee.name || "-")}</div>
          <div style="font-size: 0.85rem; color: #888;">${escapeHtml(employee.designation || "-")}</div>
        </div>
        <div style="text-align: right; font-size: 0.85rem; color: #1b5f7a; font-weight: 600;">${escapeHtml(employee.id || "-")}</div>
      </div>
    `;
  }

  function initializeStudentProfessionalSearch(inputId, dropdownId, containerId, onSelect) {
    const input = document.getElementById(inputId);
    const dropdown = document.getElementById(dropdownId);
    if (!input || !dropdown) return;
    const studentSearchIndex = (database.students || []).map(function (student) {
      return {
        id: student.id || "",
        name: student.name || "",
        className: student.className || "",
        admissionNo: student.admissionNo || "",
        nameSearch: String(student.name || "").toLowerCase(),
        admissionSearch: String(student.admissionNo || "").toLowerCase()
      };
    });

    initializeSearchWithDropdown(
      input,
      dropdown,
      function(searchTerm) {
        const matches = [];
        for (let index = 0; index < studentSearchIndex.length && matches.length < 10; index += 1) {
          const student = studentSearchIndex[index];
          if (student.nameSearch.includes(searchTerm) || student.admissionSearch.includes(searchTerm)) {
            matches.push(student);
          }
        }
        return matches;
      },
      renderStudentSearchResult,
      onSelect,
      containerId
    );
  }

  function initializeEmployeeProfessionalSearch(inputId, dropdownId, containerId, onSelect) {
    const input = document.getElementById(inputId);
    const dropdown = document.getElementById(dropdownId);
    if (!input || !dropdown) return;

    initializeSearchWithDropdown(
      input,
      dropdown,
      function(searchTerm) {
        return (database.teachers || []).filter(function(employee) {
          const name = (employee.name || "").toLowerCase();
          const phone = (employee.phone || "").toLowerCase();
          const id = (employee.id || "").toLowerCase();
          return name.includes(searchTerm) || phone.includes(searchTerm) || id.includes(searchTerm);
        });
      },
      renderEmployeeSearchResult,
      onSelect,
      containerId
    );
  }

  function extractLastIdNumber(idString) {
    if (!idString) return "";
    const match = idString.match(/\d+$/);
    return match ? match[0] : "";
  }

  function getLastStudentNumber() {
    if (!database.students || database.students.length === 0) return "";
    const numbers = database.students
      .map(s => {
        const match = String(s.admissionNo || "").match(/\d+$/);
        return match ? parseFloat(match[0], 10) : 0;
      })
      .filter(n => n > 0);
    return numbers.length > 0 ? String(Math.max(...numbers)) : "";
  }

  function getLastEmployeeNumber() {
    if (!database.teachers || database.teachers.length === 0) return "";
    const numbers = database.teachers
      .map(e => {
        const match = String(e.id || "").match(/\d+$/);
        return match ? parseFloat(match[0], 10) : 0;
      })
      .filter(n => n > 0);
    return numbers.length > 0 ? String(Math.max(...numbers)) : "";
  }

  function downloadBackupData() {
    refreshDatabase();
    const license = ensureLicenseSettings();
    const backupPayload = {
      exportType: "sagarsoft-secure-backup",
      version: 1,
      createdAt: new Date().toISOString(),
      schoolId: String(license.schoolId || ""),
      schoolName: String(license.schoolName || database.school.name || ""),
      data: database
    };
    const payload = `SSMS-BACKUP-${toBase64Unicode(JSON.stringify(backupPayload))}`;
    if (payload === "SSMS-BACKUP-") {
      throw new Error("Unable to encode backup data.");
    }
    sessionStorage.setItem("sagarsoft_auto_backup_latest", payload);
    const blob = new Blob([payload], { type: "application/octet-stream" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `sagarsoft-secure-backup-${new Date().toISOString().slice(0, 10)}.ssmsbackup`;
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    window.setTimeout(function () {
      URL.revokeObjectURL(url);
    }, 1000);
  }

  function parseSecureBackupFile(rawContent) {
    const raw = String(rawContent || "").trim();
    if (!raw.startsWith("SSMS-BACKUP-")) {
      return { ok: false, message: "Invalid SagarSoft backup file." };
    }
    const decoded = fromBase64Unicode(raw.replace("SSMS-BACKUP-", ""));
    if (!decoded) {
      return { ok: false, message: "Unable to read backup file." };
    }
    try {
      const payload = JSON.parse(decoded);
      if (!payload || payload.exportType !== "sagarsoft-secure-backup" || !payload.data) {
        return { ok: false, message: "Backup file format is not supported." };
      }
      return { ok: true, data: payload.data, meta: payload };
    } catch (error) {
      return { ok: false, message: "Backup file is corrupted." };
    }
  }

  function restoreSecureBackupData(nextDatabase) {
    if (!nextDatabase || typeof nextDatabase !== "object") {
      return { ok: false, message: "Backup data is empty." };
    }
    window.SagarSoftDB.saveDatabase(nextDatabase);
    database = window.SagarSoftDB.getDatabase();
    ensureLicenseSettings();
    ensurePortalSyncData();
    normalizeStudentsDatasetInMemory();
    saveDatabase();
    return { ok: true, message: "Backup restored successfully. The app will reload now." };
  }

  function exportSchoolControlSnapshot() {
    const license = ensureLicenseSettings();
    const profile = (database.generalSettings && database.generalSettings.instituteProfile) || {};
    const snapshot = {
      exportType: "school-control-summary",
      exportedAt: new Date().toISOString(),
      school: {
        schoolId: String(license.schoolId || "").trim(),
        schoolName: String(license.schoolName || profile.name || database.school.name || "").trim(),
        logo: String(profile.logo || ""),
        activated: Boolean(license.activated),
        status: String(license.status || (license.activated ? "active" : "inactive")),
        plan: String(license.subscriptionPlan || "monthly"),
        startDate: String(license.startDate || ""),
        expiryDate: String(license.expiryDate || "")
      },
      metrics: {
        totalStudents: Array.isArray(database.students) ? database.students.length : 0
      }
    };
    const payload = JSON.stringify(snapshot, null, 2);
    const blob = new Blob([payload], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `sagarsoft-school-summary-${(snapshot.school.schoolId || "school").replace(/[^a-z0-9-_]/gi, "")}-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    URL.revokeObjectURL(url);
  }

  function exportOfflineUpdatePackage() {
    const safeClone = function (value, fallback) {
      try {
        return JSON.parse(JSON.stringify(value));
      } catch (error) {
        return fallback;
      }
    };
    const packageBody = {
      packageType: "sagarsoft-offline-update",
      packageVersion: "1.0.0",
      generatedAt: new Date().toISOString(),
      generatedBy: {
        userId: currentUser.id,
        name: currentUser.name,
        role: currentUser.role
      },
      updateData: {
        generalSettings: safeClone(database.generalSettings || {}, {}),
        school: safeClone(database.school || {}, {}),
        classSubjects: safeClone(database.classSubjects || {}, {}),
        classes: safeClone(database.classes || [], []),
        versionTag: `UPDATE-${new Date().toISOString().slice(0, 10)}`
      }
    };
    const payload = JSON.stringify(packageBody, null, 2);
    const blob = new Blob([payload], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `sagarsoft-update-package-${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    URL.revokeObjectURL(url);
  }

  function applyOfflineUpdatePackage(pkg) {
    if (!pkg || pkg.packageType !== "sagarsoft-offline-update" || !pkg.updateData) {
      return { ok: false, message: "Invalid update package format." };
    }
    const data = pkg.updateData || {};
    if (data.generalSettings && typeof data.generalSettings === "object") {
      const currentLicense = ensureLicenseSettings();
      const nextSettings = JSON.parse(JSON.stringify(data.generalSettings));
      // Keep local license status to avoid unintended lock.
      if (!nextSettings.licenseSettings) {
        nextSettings.licenseSettings = {};
      }
      nextSettings.licenseSettings = {
        ...nextSettings.licenseSettings,
        activated: currentLicense.activated,
        status: currentLicense.status,
        schoolId: currentLicense.schoolId,
        schoolName: currentLicense.schoolName,
        startDate: currentLicense.startDate,
        expiryDate: currentLicense.expiryDate
      };
      database.generalSettings = nextSettings;
    }
    if (data.school && typeof data.school === "object") {
      database.school = { ...database.school, ...data.school };
    }
    if (data.classSubjects && typeof data.classSubjects === "object") {
      database.classSubjects = data.classSubjects;
    }
    if (Array.isArray(data.classes)) {
      database.classes = data.classes;
    }
    addActivity("Offline update imported", `Update package applied (${data.versionTag || "latest"}).`);
    saveDatabase();
    refreshDatabase();
    applySavedThemeSettings();
    applyRouteAccessVisibility();
    return { ok: true, message: "Offline update package imported successfully." };
  }

  function ensureOfflineSchoolsRegistry() {
    if (!database.generalSettings) {
      database.generalSettings = {};
    }
    if (!Array.isArray(database.generalSettings.offlineSchoolsRegistry)) {
      database.generalSettings.offlineSchoolsRegistry = [];
    }
    return database.generalSettings.offlineSchoolsRegistry;
  }

  function upsertSchoolRegistryFromLicense(licenseSnapshot) {
    const license = licenseSnapshot || ensureLicenseSettings();
    const schoolId = String(license.schoolId || "").trim();
    if (!schoolId) {
      return;
    }
    const profile = (database.generalSettings && database.generalSettings.instituteProfile) || {};
    const registry = ensureOfflineSchoolsRegistry();
    const row = {
      schoolId: schoolId,
      schoolName: String(license.schoolName || profile.name || database.school.name || "").trim(),
      logo: String(profile.logo || ""),
      activated: Boolean(license.activated),
      status: String(license.status || (license.activated ? "active" : "inactive")),
      plan: String(license.subscriptionPlan || "monthly"),
      startDate: String(license.startDate || ""),
      expiryDate: String(license.expiryDate || ""),
      totalStudents: Array.isArray(database.students) ? database.students.length : 0,
      importedAt: new Date().toISOString()
    };
    const existingIndex = registry.findIndex(function (item) {
      return String(item.schoolId || "").trim().toLowerCase() === schoolId.toLowerCase();
    });
    if (existingIndex >= 0) {
      registry[existingIndex] = { ...registry[existingIndex], ...row };
    } else {
      registry.unshift(row);
    }
  }

  function getSubscriptionStatusMeta(expiryDate) {
    const raw = String(expiryDate || "").trim();
    if (!raw) {
      return { label: "No Expiry", tone: "warning", daysLeft: null };
    }
    const exp = new Date(raw);
    if (Number.isNaN(exp.getTime())) {
      return { label: "Invalid Expiry", tone: "error", daysLeft: null };
    }
    const now = new Date();
    const startToday = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
    const startExp = new Date(exp.getFullYear(), exp.getMonth(), exp.getDate()).getTime();
    const diff = Math.floor((startExp - startToday) / (1000 * 60 * 60 * 24));
    if (diff < 0) {
      return { label: `Expired (${Math.abs(diff)} day${Math.abs(diff) === 1 ? "" : "s"} ago)`, tone: "error", daysLeft: diff };
    }
    if (diff <= 7) {
      return { label: `Expiring soon (${diff} day${diff === 1 ? "" : "s"} left)`, tone: "warning", daysLeft: diff };
    }
    return { label: `Active (${diff} days left)`, tone: "success", daysLeft: diff };
  }

  function runSuperAdminExpiryAlerts() {
    if (currentUser.role !== superAdminRole) {
      return;
    }
    const rows = ensureOfflineSchoolsRegistry();
    if (!rows.length) {
      return;
    }
    let alertState = {};
    try {
      alertState = JSON.parse(sessionStorage.getItem("sagarsoft_super_expiry_alert_state") || "{}") || {};
    } catch (error) {
      alertState = {};
    }
    let changed = false;
    rows.forEach(function (row) {
      const key = String(row.schoolId || "").trim().toLowerCase();
      if (!key) {
        return;
      }
      const meta = getSubscriptionStatusMeta(row.expiryDate);
      const stamp = `${String(row.expiryDate || "")}|${meta.tone}`;
      if (meta.tone === "error" || meta.tone === "warning") {
        if (alertState[key] !== stamp) {
          const title = meta.tone === "error" ? "Error" : "Warning";
          openAppMessageBox(title, `${row.schoolName || row.schoolId}: ${meta.label}`, meta.tone === "error" ? "error" : "warning");
          alertState[key] = stamp;
          changed = true;
        }
      } else if (alertState[key]) {
        delete alertState[key];
        changed = true;
      }
    });
    if (changed) {
      sessionStorage.setItem("sagarsoft_super_expiry_alert_state", JSON.stringify(alertState));
    }
  }

  function updateTopProfileIdentity() {
    const license = ensureLicenseSettings();
    const profile = (database.generalSettings && database.generalSettings.instituteProfile) || {};
    const roleLabel = getRoleLabel(currentUser.role);
    let displayName = currentUser.name || "User";
    let displayAvatarHtml = getInitials(displayName);

    if (currentUser.role !== superAdminRole && license.activated) {
      displayName = profile.name || license.schoolName || database.school.name || displayName;
      if (profile.logo) {
        displayAvatarHtml = `<img src="${escapeAttr(profile.logo)}" alt="School logo" style="width:100%;height:100%;object-fit:cover;border-radius:50%;">`;
      } else {
        displayAvatarHtml = getInitials(displayName);
      }
    }

    profileName.textContent = displayName;
    profileRole.textContent = roleLabel;
    if (String(displayAvatarHtml || "").includes("<img")) {
      profileAvatar.innerHTML = displayAvatarHtml;
    } else {
      profileAvatar.textContent = displayAvatarHtml;
    }
  }

  function getApiBaseUrl() {
    return window.SagarSoftOnlineConfig && window.SagarSoftOnlineConfig.apiBaseUrl
      ? window.SagarSoftOnlineConfig.apiBaseUrl.replace(/\/+$/, "")
      : "https://sagarsoftonline.onrender.com";
  }

  function getLastBackupTime() {
    var backups = database.settings && database.settings.backupHistory;
    if (!Array.isArray(backups) || !backups.length) return null;
    return backups[backups.length - 1].createdAt;
  }

  async function backupToSupabase() {
    var schoolId = (ensureLicenseSettings().schoolId || "").trim();
    var isDemo = currentUser && (currentUser.email || "").endsWith("@sagarsoft.com");
    if (!schoolId && isDemo) {
      schoolId = "DEMO-SCHOOL-" + Date.now();
    }
    if (!schoolId) {
      openAppMessageBox("Backup Failed", "No school ID configured. Go to Account Settings to set up your school.", "error");
      return false;
    }
    try {
      var dataToSend = {};
      try { dataToSend = JSON.parse(JSON.stringify(database)); } catch (_e) { dataToSend = database; }
      var payload = { school_id: schoolId, database: dataToSend };
      var controller = new AbortController();
      var timeoutId = setTimeout(function () { controller.abort(); }, 15000);
      var resp = await fetch(getApiBaseUrl() + "/api/backup", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
        signal: controller.signal
      });
      clearTimeout(timeoutId);
      var data = await resp.json().catch(function () { return {}; });
      if (data.success) {
        database.settings = database.settings || {};
        database.settings.backupHistory = database.settings.backupHistory || [];
        database.settings.backupHistory.push({ createdAt: new Date().toISOString(), sizeBytes: data.size_bytes || 0 });
        if (database.settings.backupHistory.length > 50) database.settings.backupHistory = database.settings.backupHistory.slice(-50);
        saveDatabase();
        return true;
      }
      return false;
    } catch (e) {
      if (e && e.name === "AbortError") {
        openAppMessageBox("Backup Failed", "Request timed out. The server might be waking up. Try again in 30 seconds.", "error");
      } else {
        openAppMessageBox("Backup Failed", "Could not reach server. Make sure " + getApiBaseUrl() + " is accessible.", "error");
      }
      return false;
    }
  }

  async function checkForUpdates() {
    try {
      var controller = new AbortController();
      var timeoutId = setTimeout(function () { controller.abort(); }, 10000);
      var resp = await fetch(getApiBaseUrl() + "/api/version", { signal: controller.signal });
      clearTimeout(timeoutId);
      var data = await resp.json().catch(function () { return {}; });
      var currentVersion = "1.0.0";
      if (data.version && data.version !== currentVersion) {
        openAppConfirm("Update Available", "Version " + data.version + " is available.\nRelease date: " + (data.releaseDate || "-") + "\n\n" + (data.releaseNotes || "") + "\n\nOpen the app to get the latest features?", "info").then(function (go) {
          if (go && data.updateUrl) {
            window.open(data.updateUrl, "_blank");
          }
        });
      } else {
        openAppMessageBox("Up to Date", "You are running the latest version (" + currentVersion + ").", "success");
      }
    } catch (_e) {
      openAppMessageBox("Update Check Failed", "Could not check for updates. Make sure " + getApiBaseUrl() + " is accessible.", "error");
    }
  }

  function renderProfileDropdownMenu() {
    if (!profileDropdown) {
      return;
    }
    const isSuperAdmin = currentUser.role === superAdminRole;
    const license = ensureLicenseSettings();
    const isUnverifiedSchool = !isSuperAdmin && !license.activated;
    var lastBackup = getLastBackupTime();
    var lastBackupLabel = lastBackup ? "Backup: " + new Date(lastBackup).toLocaleString() : "";

    var commonButtons = `
      <button class="dropdown-link" id="backupNowBtn" type="button">${lastBackupLabel ? "Backup (" + new Date(lastBackup).toLocaleDateString() + ")" : "Backup Data"}</button>
      <button class="dropdown-link" id="checkUpdateBtn" type="button">Check Updates</button>
    `;

    if (isUnverifiedSchool) {
      profileDropdown.innerHTML = `
        ${commonButtons}
        <button class="dropdown-link" id="openAccountSettingsMenuBtn" type="button">Open Settings</button>
        <button class="dropdown-link danger" id="logoutBtn" type="button">Logout</button>
      `;
      bindDropdownButtons();
      return;
    }
    profileDropdown.innerHTML = (isSuperAdmin
      ? `
        <button class="dropdown-link" id="openSettingsMenuBtn" type="button">Open Settings</button>
        <div class="dropdown-submenu" id="settingsSubmenu" hidden>
          <button class="dropdown-link" id="activateSchoolAccountMenuBtn" type="button">Activate School Account</button>
        </div>
      `
      : `
        <button class="dropdown-link" id="openAccountSettingsMenuBtn" type="button">Open Settings</button>
      `) +
      commonButtons +
      `<button class="dropdown-link danger" id="logoutBtn" type="button">Logout</button>`;

    bindDropdownButtons();
  }

  function bindDropdownButtons() {
    logoutButton = document.getElementById("logoutBtn");
    const openAccountSettingsMenuBtn = document.getElementById("openAccountSettingsMenuBtn");
    const openSettingsMenuBtn = document.getElementById("openSettingsMenuBtn");
    const activateSchoolAccountMenuBtn = document.getElementById("activateSchoolAccountMenuBtn");
    const settingsSubmenu = document.getElementById("settingsSubmenu");
    const backupNowBtn = document.getElementById("backupNowBtn");
    const checkUpdateBtn = document.getElementById("checkUpdateBtn");

    if (openAccountSettingsMenuBtn) {
      openAccountSettingsMenuBtn.addEventListener("click", function () {
        setRoute("account-settings");
      });
    }

    if (openSettingsMenuBtn && settingsSubmenu) {
      openSettingsMenuBtn.addEventListener("click", function () {
        settingsSubmenu.hidden = !settingsSubmenu.hidden;
      });
    }

    if (activateSchoolAccountMenuBtn) {
      activateSchoolAccountMenuBtn.addEventListener("click", function () {
        setRoute("account-settings");
      });
    }

    if (backupNowBtn) {
      backupNowBtn.addEventListener("click", async function () {
        backupNowBtn.textContent = "Backing up...";
        backupNowBtn.disabled = true;
        var ok = await backupToSupabase();
        backupNowBtn.textContent = ok ? "Backup Done" : "Backup Failed";
        backupNowBtn.disabled = false;
        if (ok) {
          openAppMessageBox("Backup Complete", "Your data has been backed up to Supabase.", "success");
          renderProfileDropdownMenu();
        } else {
          openAppMessageBox("Backup Failed", "Could not backup data. Check your internet connection.", "error");
        }
      });
    }

    if (checkUpdateBtn) {
      checkUpdateBtn.addEventListener("click", function () {
        checkUpdateBtn.textContent = "Checking...";
        checkUpdateBtn.disabled = true;
        checkForUpdates().then(function () {
          checkUpdateBtn.textContent = "Check Updates";
          checkUpdateBtn.disabled = false;
        }).catch(function () {
          checkUpdateBtn.textContent = "Check Updates";
          checkUpdateBtn.disabled = false;
        });
      });
    }

    if (logoutButton) {
      logoutButton.addEventListener("click", function () {
        window.SagarSoftAuth.logout();
        window.location.href = "./login.html";
      });
    }
  }

  function ensurePortalSyncData() {
    if (!Array.isArray(database.notifications)) {
      database.notifications = [];
    }
    if (!database.portalSync) {
      database.portalSync = { appliedNotificationIds: [], appliedActivationIds: [] };
    }
    if (!Array.isArray(database.portalSync.appliedNotificationIds)) {
      database.portalSync.appliedNotificationIds = [];
    }
    if (!Array.isArray(database.portalSync.appliedActivationIds)) {
      database.portalSync.appliedActivationIds = [];
    }
  }

  function applySidebarIcons() {
    const iconMapByRoute = {
      "dashboard": "dashboard.png",
      "homework": "homework.png",
      "whatsapp": "whatsapp.png",
      "sms-services": "SMS Services.png"
    };
    const iconMapByAccordion = {
      "general-settings": "cogwheel.png",
      "classes": "classes.png",
      "subjects": "subjects.png",
      "students": "students.png",
      "employees": "employees.png",
      "accounts": "accounts.png",
      "fees": "fees.png",
      "salary": "salary.png",
      "attendance": "attendance.png",
      "timetable": "timetable.png",
      "question-paper": "question paper.png",
      "exams": "exams.png",
      "class-tests": "class test.png",
      "reports": "reports.png",
      "certificates": "Certificates.png"
    };

    document.querySelectorAll(".menu-link .menu-icon, .menu-group__trigger .menu-icon").forEach(function (iconEl) {
      const parent = iconEl.closest(".menu-link, .menu-group__trigger");
      if (!parent) {
        return;
      }
      const route = parent.dataset.route || "";
      const accordion = parent.dataset.accordion || "";
      const fileName = iconMapByRoute[route] || iconMapByAccordion[accordion] || "";
      if (!fileName) {
        return;
      }
      iconEl.classList.remove("menu-icon--whatsapp");
      if (route === "whatsapp") {
        iconEl.classList.add("menu-icon--whatsapp");
      }
      iconEl.innerHTML = `<img src="./assets/${encodeURI(fileName)}" alt="" class="menu-icon__img">`;
      iconEl.setAttribute("aria-hidden", "true");
    });
  }

  function renderNotificationList() {
    if (!notificationList) {
      return;
    }
    ensurePortalSyncData();
    const rows = (database.notifications || []).slice().sort(function (a, b) {
      return new Date(b.createdAt || 0).getTime() - new Date(a.createdAt || 0).getTime();
    });
    const unread = rows.filter(function (item) { return !item.read; }).length;
    if (notificationDot) {
      notificationDot.style.display = unread > 0 ? "inline-flex" : "none";
    }
    if (!rows.length) {
      notificationList.innerHTML = `<div class="notification-item"><p>No notifications yet.</p></div>`;
      return;
    }
    notificationList.innerHTML = rows.slice(0, 60).map(function (item) {
      return `
        <article class="notification-item ${item.read ? "" : "unread"}">
          <strong>${escapeHtml(item.title || "Notification")}</strong>
          <p>${escapeHtml(item.message || "-")}</p>
          <time>${escapeHtml(item.createdAt ? new Date(item.createdAt).toLocaleString() : "-")}</time>
        </article>
      `;
    }).join("");
  }

  function syncPortalActivationAndNotifications() {
    renderNotificationList();
  }

  function escapePrintHtml(value) {
    return String(value || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
  }

  function escapePrintAttr(value) {
    return escapePrintHtml(value).replace(/"/g, "&quot;");
  }

  function ensureSmsCommunicationSettings() {
    if (!database.generalSettings) {
      database.generalSettings = {};
    }
    if (!database.generalSettings.smsGateway) {
      database.generalSettings.smsGateway = {
        provider: "simple-sms-gateway",
        connectedNumber: "",
        baseUrl: "",
        apiKey: "",
        connected: false,
        connectedAt: "",
        lastHeartbeat: ""
      };
    }
    if (!Array.isArray(database.generalSettings.smsOutbox)) {
      database.generalSettings.smsOutbox = [];
    }
    return database.generalSettings;
  }

  function normalizeSmsPhone(value) {
    return String(value || "").replace(/[^\d+]/g, "");
  }

  function normalizeWhatsappPhone(value) {
    const smsNormalized = normalizeSmsPhone(value || "");
    let digits = String(smsNormalized || "").replace(/[^\d]/g, "");
    if (!digits) {
      return "";
    }
    if (digits.startsWith("00")) {
      digits = digits.slice(2);
    }
    if (digits.startsWith("92") && digits.length >= 12) {
      return digits;
    }
    if (digits.startsWith("0") && digits.length === 11) {
      return `92${digits.slice(1)}`;
    }
    if (digits.length === 10) {
      return `92${digits}`;
    }
    return digits;
  }

  function getStudentWhatsappPhone(student) {
    const record = student || {};
    return normalizeSmsPhone(
      record.whatsappNumber ||
      record.whatsappNo ||
      record.whatsappPhone ||
      record.phone ||
      record.mobile ||
      record.studentPhone ||
      record.fatherPhone ||
      ""
    );
  }

  function getStudentDisplayPhone(student) {
    const record = student || {};
    return (
      record.whatsappNumber ||
      record.whatsappNo ||
      record.whatsappPhone ||
      record.phone ||
      record.studentPhone ||
      record.mobile ||
      record.mobileNo ||
      record.fatherPhone ||
      "-"
    );
  }

  function isStudentWhatsappActive(student) {
    const record = student || {};
    const phone = getStudentWhatsappPhone(record);
    if (!phone) {
      return false;
    }
    const status = String(record.whatsappStatus || "").trim().toLowerCase();
    const activeFlag = String(record.whatsappActive || "").trim().toLowerCase();
    const enabledFlag = String(record.whatsappEnabled || "").trim().toLowerCase();
    if (status === "inactive" || activeFlag === "false" || enabledFlag === "false") {
      return false;
    }
    return true;
  }

  function normalizeSmsGatewayUrl(value) {
    const raw = String(value || "").trim().replace(/\/+$/, "");
    if (!raw) {
      return "";
    }
    if (/^https?:\/\//i.test(raw)) {
      return raw;
    }
    return `http://${raw}`;
  }

  function interpolateTemplate(template, data) {
    var text = String(template || "");
    text = text.replace(/\{Mr\.?\/Ms\.?\}/gi, "{prefix}");
    return text.replace(/\{(\w+)\}/g, function (_, key) {
      return typeof data[key] === "undefined" ? "" : String(data[key]);
    });
  }

  function getDefaultAdmissionLetterTemplate() {
    return "Admission confirmed: {name} (Roll {roll}) in class {class}. Admission Date: {admissionDate}. Welcome to {school}.";
  }

  function getDefaultStaffIdCardTemplate() {
    return "Dear Mr/Ms {Name} your staff id card has been prepared. please visit office and receive your id card.Thanks\nBest regard.\n{school}";
  }

  function getDefaultJobLetterTemplate() {
    return "Dear {Gender} {Name},\nyou are appointed as {Role} at {school}. we look forward to your valuable contribution to our institution. Thanks\nRegards\n{school}";
  }

  function getDefaultStudentIdCardTemplate() {
    return "Dear Mr/Ms {Name} your student id card has been prepared. please visit office and receive your id card.Thanks\nBest regard.\n{school}";
  }

  async function fetchWithTimeout(url, options, timeoutMs) {
    const safeTimeout = Number(timeoutMs || 3500);
    const controller = new AbortController();
    const timer = setTimeout(function () {
      controller.abort();
    }, safeTimeout);
    try {
      return await fetch(url, {
        ...(options || {}),
        signal: controller.signal
      });
    } finally {
      clearTimeout(timer);
    }
  }

  function chooseCommunicationChannel(contextLabel) {
    const choice = window.prompt(`Select channel for ${contextLabel}:\n1. SMS\n2. WhatsApp`, "1");
    const normalized = String(choice || "").trim().toLowerCase();
    if (!normalized) {
      return "";
    }
    if (normalized === "1" || normalized === "sms") {
      return "sms";
    }
    if (normalized === "2" || normalized === "whatsapp" || normalized === "wa") {
      return "whatsapp";
    }
    return "";
  }

  function pushSmsOutboxEntry(entry) {
    const settings = ensureSmsCommunicationSettings();
    settings.smsOutbox.unshift({
      id: entry.id || `SMS-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
      recipientName: entry.recipientName || "-",
      recipientPhone: entry.recipientPhone || "",
      message: entry.message || "",
      status: entry.status || "queued",
      source: entry.source || "Manual SMS",
      recipientType: entry.recipientType || "student",
      campaignType: entry.campaignType || "manual",
      createdAt: entry.createdAt || new Date().toLocaleString()
    });
    saveDatabase();
    return settings.smsOutbox[0];
  }

  async function sendSmsViaConnectedGateway(payload) {
    const settings = ensureSmsCommunicationSettings();
    const gateway = settings.smsGateway || {};
    const phone = normalizeSmsPhone(payload.recipientPhone || "");
    const messageText = String(payload.message || "").trim();
    const baseEntry = {
      recipientName: payload.recipientName || "-",
      recipientPhone: phone || String(payload.recipientPhone || ""),
      message: messageText || String(payload.message || ""),
      source: payload.source || "Manual SMS",
      recipientType: payload.recipientType || "student",
      campaignType: payload.campaignType || "manual"
    };
    if (!gateway.connected) {
      const failedItem = pushSmsOutboxEntry({
        ...baseEntry,
        status: "failed"
      });
      return { success: false, reason: "gateway-disconnected", outboxItem: failedItem };
    }
    if (!phone) {
      const failedItem = pushSmsOutboxEntry({
        ...baseEntry,
        status: "failed"
      });
      return { success: false, reason: "phone-missing", outboxItem: failedItem };
    }
    if (!messageText) {
      const failedItem = pushSmsOutboxEntry({
        ...baseEntry,
        status: "failed"
      });
      return { success: false, reason: "message-missing", outboxItem: failedItem };
    }
    const outboxItem = pushSmsOutboxEntry({
      ...baseEntry,
      recipientPhone: phone,
      message: messageText,
      status: "queued"
    });
    const baseUrl = normalizeSmsGatewayUrl(gateway.baseUrl || "");
    const endpoints = ["/send-sms", "/send", "/api/send-sms"];
    const headers = { "Content-Type": "application/json" };
    if (gateway.apiKey) {
      headers.Authorization = `Bearer ${gateway.apiKey}`;
    }
    const urlsToTry = [baseUrl];
    var portFallback = "";
    var portMatch = baseUrl.match(/:(\d+)(?:\/|$)/);
    if (portMatch) {
      portFallback = "http://127.0.0.1:" + portMatch[1];
      urlsToTry.push(portFallback);
    }
    let success = false;
    for (let u = 0; u < urlsToTry.length; u++) {
      const urlBase = urlsToTry[u];
      for (let index = 0; index < endpoints.length; index += 1) {
        const endpoint = endpoints[index];
        try {
          const response = await fetchWithTimeout(`${urlBase}${endpoint}`, {
            method: "POST",
            headers: headers,
            body: JSON.stringify({ phone: phone, message: messageText })
          }, 3500);
          if (response.ok || response.type === "opaque") {
            success = true;
            break;
          }
        } catch (error) {
          try {
            await fetchWithTimeout(`${urlBase}${endpoint}`, {
              method: "POST",
              mode: "no-cors",
              headers: { "Content-Type": "text/plain;charset=UTF-8" },
              body: JSON.stringify({ phone: phone, message: messageText })
            }, 3500);
            success = true;
            break;
          } catch (innerError) {
            // Try next endpoint.
          }
        }
      }
      if (success) break;
    }
    outboxItem.status = success ? "sent" : "failed";
    if (success) {
      settings.smsGateway.lastHeartbeat = new Date().toLocaleString();
    }
    saveDatabase();
    return { success: success, outboxItem: outboxItem };
  }

  var _supabase = null;

  function getSupabaseConfig() {
    return (database.generalSettings && database.generalSettings.supabaseConfig) || {};
  }

  function initSupabase() {
    if (_supabase) return _supabase;
    var cfg = getSupabaseConfig();
    if (!cfg.url || !cfg.anonKey) return null;
    try {
      _supabase = window.supabase.createClient(cfg.url, cfg.anonKey, { auth: { persistSession: false } });
      return _supabase;
    } catch (e) {
      console.error("Supabase init failed:", e);
      return null;
    }
  }

  async function ensureSupabaseTables() {
    var cfg = getSupabaseConfig();
    if (!cfg.url || !cfg.anonKey) return { ok: false, reason: "not-configured" };
    if (cfg.tablesCreated) return { ok: true };
    try {
      var sb = initSupabase();
      if (!sb) return { ok: false, reason: "init-failed" };
      var test = await sb.from("sms_queue").select("id").limit(1);
      if (test.error && test.error.code === "42P01") {
        if (!cfg.serviceRoleKey) return { ok: false, reason: "tables-missing" };
        var sql = [
          "CREATE TABLE IF NOT EXISTS sms_queue (",
          "  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,",
          "  school_id UUID NOT NULL,",
          "  device_id UUID,",
          "  recipient_phone TEXT NOT NULL,",
          "  message TEXT NOT NULL,",
          "  status TEXT DEFAULT 'pending',",
          "  source TEXT DEFAULT 'Manual SMS',",
          "  campaign_type TEXT DEFAULT 'manual',",
          "  recipient_name TEXT,",
          "  recipient_type TEXT DEFAULT 'student',",
          "  error_message TEXT,",
          "  sent_at TIMESTAMPTZ,",
          "  created_at TIMESTAMPTZ DEFAULT now()",
          ");",
          "CREATE TABLE IF NOT EXISTS devices (",
          "  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,",
          "  school_id UUID NOT NULL,",
          "  device_name TEXT,",
          "  device_id TEXT NOT NULL UNIQUE,",
          "  is_active BOOLEAN DEFAULT false,",
          "  sim_number TEXT,",
          "  last_poll_at TIMESTAMPTZ,",
          "  created_at TIMESTAMPTZ DEFAULT now()",
          ");"
        ].join(" ");
        var res = await fetch(cfg.url + "/rest/v1/rpc/", {
          method: "POST",
          headers: { "Content-Type": "application/json", "apikey": cfg.serviceRoleKey, "Authorization": "Bearer " + cfg.serviceRoleKey },
          body: JSON.stringify({ query: sql })
        });
        if (!res.ok) {
          var altRes = await fetch(cfg.url + "/rest/v1/", {
            method: "POST",
            headers: { "Content-Type": "application/json", "Prefer": "resolution=merge-duplicates", "apikey": cfg.serviceRoleKey, "Authorization": "Bearer " + cfg.serviceRoleKey }
          });
        }
      }
      cfg.tablesCreated = true;
      saveDatabase();
      return { ok: true };
    } catch (e) {
      console.error("Table creation error:", e);
      return { ok: false, reason: "error", error: e.message };
    }
  }

  async function sendSmsViaQueue(payload) {
    var sb = initSupabase();
    if (!sb) return { success: false, reason: "supabase-not-configured" };
    var cfg = getSupabaseConfig();
    if (!cfg.tablesCreated) {
      var initResult = await ensureSupabaseTables();
      if (!initResult.success) return { success: false, reason: "table-init-failed", error: initResult.error };
      cfg.tablesCreated = true;
      if (database.generalSettings && database.generalSettings.supabaseConfig) {
        database.generalSettings.supabaseConfig.tablesCreated = true;
      }
    }
    try {
      var schoolId = database.school && database.school.id;
      if (!schoolId) return { success: false, reason: "school-id-missing" };
      var phone = normalizeSmsPhone(payload.recipientPhone || "");
      var messageText = String(payload.message || "").trim();
      if (!phone) return { success: false, reason: "phone-missing" };
      if (!messageText) return { success: false, reason: "message-missing" };
      var { data, error } = await sb.from("sms_queue").insert({
        school_id: schoolId,
        recipient_phone: phone,
        message: messageText,
        source: payload.source || "Manual SMS",
        campaign_type: payload.campaignType || "manual",
        recipient_name: payload.recipientName || "-",
        recipient_type: payload.recipientType || "student",
        status: "pending"
      }).select("id").single();
      if (error) return { success: false, reason: "db-error", error: error.message };
      var outboxItem = pushSmsOutboxEntry({
        id: data && data.id ? String(data.id) : "",
        recipientName: payload.recipientName || "-",
        recipientPhone: phone,
        message: messageText,
        status: "queued",
        source: payload.source || "Manual SMS",
        recipientType: payload.recipientType || "student",
        campaignType: payload.campaignType || "manual"
      });
      return { success: true, outboxItem: outboxItem };
    } catch (e) {
      return { success: false, reason: "exception", error: e.message };
    }
  }

  async function sendSmsSmart(payload) {
    var cfg = getSupabaseConfig();
    if (cfg && cfg.url && cfg.anonKey && window.supabase) {
      return await sendSmsViaQueue(payload);
    }
    return await sendSmsViaConnectedGateway(payload);
  }

  function openWhatsAppWithFallback(appUrl, webUrl) {
    if (isMobileRuntime()) {
      window.open(appUrl, "_blank");
      return true;
    }
    var popup = window.open(webUrl, "sagarsoftWhatsappPopup", "width=980,height=760,scrollbars=yes,resizable=yes");
    if (!popup) {
      popup = openCenteredWindow(webUrl, "sagarsoftWhatsappPopup");
    }
    return true;
  }

  function logWhatsappCommunication(payload) {
    const phone = normalizeSmsPhone(payload.recipientPhone || "");
    const messageText = String(payload.message || "").trim();
    const openChat = !(payload && payload.openChat === false);
    if (!phone || !messageText) {
      return false;
    }
    const whatsappPhone = normalizeWhatsappPhone(phone);
    const encodedPhone = encodeURIComponent(whatsappPhone || "");
    const encodedText = encodeURIComponent(messageText);
    const appUrl = "whatsapp://send?phone=" + encodedPhone + "&text=" + encodedText;
    const webUrl = "https://wa.me/" + encodedPhone + "?text=" + encodedText;
    var opened = false;
    if (openChat) {
      opened = openWhatsAppWithFallback(appUrl, webUrl);
    }
    pushSmsOutboxEntry({
      recipientName: payload.recipientName || "-",
      recipientPhone: phone,
      message: messageText,
      source: payload.source || "WhatsApp",
      recipientType: payload.recipientType || "student",
      campaignType: payload.campaignType || "manual",
      status: opened ? "opened" : "prepared"
    });
    if (openChat && !opened) {
      openAppMessageBox("Error", "WhatsApp could not open. Please allow popups and make sure WhatsApp Web is logged in on your PC.", "error");
    }
    return true;
  }

  async function saveCommunicationPdf(html, fileName) {
    if (window.SagarSoftDesktop && typeof window.SagarSoftDesktop.savePdf === "function") {
      return window.SagarSoftDesktop.savePdf({ html: html, fileName: fileName });
    }
    await openPrintHtmlWindow(html);
    return { success: true, filePath: fileName };
  }

  function openCenteredWindow(url, windowName) {
    if (window.SagarSoftDesktop && typeof window.SagarSoftDesktop.openExternal === "function") {
      window.SagarSoftDesktop.openExternal(url).catch(function () {
        return null;
      });
      return true;
    }
    const width = 980;
    const height = 760;
    const dualScreenLeft = window.screenLeft !== undefined ? window.screenLeft : window.screenX;
    const dualScreenTop = window.screenTop !== undefined ? window.screenTop : window.screenY;
    const viewportWidth = window.innerWidth || document.documentElement.clientWidth || screen.width;
    const viewportHeight = window.innerHeight || document.documentElement.clientHeight || screen.height;
    const left = Math.max(0, Math.round(dualScreenLeft + (viewportWidth - width) / 2));
    const top = Math.max(0, Math.round(dualScreenTop + (viewportHeight - height) / 2));
    const features = `toolbar=no,location=no,status=no,menubar=no,scrollbars=yes,resizable=yes,width=${width},height=${height},left=${left},top=${top}`;
    return window.open(url, windowName || "_blank", features);
  }

  function isMobileRuntime() {
    return /Android|iPhone|iPad|iPod/i.test(navigator.userAgent || "") || (window.matchMedia && window.matchMedia("(max-width: 760px)").matches);
  }

  function getWhatsappOpenUrl(phone, text) {
    const normalizedPhone = normalizeWhatsappPhone(phone);
    const encodedPhone = encodeURIComponent(normalizedPhone || "");
    const encodedText = encodeURIComponent(String(text || ""));
    if (isMobileRuntime()) {
      return `whatsapp://send?phone=${encodedPhone}&text=${encodedText}`;
    }
    return `https://wa.me/${encodedPhone}?text=${encodedText}`;
  }

  function sendDirectWhatsappToStudent(student, contextLabel, presetMessage) {
    const normalizedStudent = normalizeStudentForPrint(student || {});
    const recipientPhone = getStudentWhatsappPhone(student || normalizedStudent);
    if (!recipientPhone || !isStudentWhatsappActive(student || normalizedStudent)) {
      openAppMessageBox("Error", "The student is not active account on whatsapp with this number.", "error");
      return false;
    }
    const defaultMessage = `Dear ${normalizedStudent.name || "Student"}, this is a message from ${database.school.name || "School"}.`;
    const messageText = String(presetMessage || defaultMessage).trim();
    if (!messageText) {
      return false;
    }
    const logged = logWhatsappCommunication({
      recipientName: normalizedStudent.name || "-",
      recipientPhone: recipientPhone,
      message: messageText,
      source: "Student Direct WhatsApp",
      recipientType: "student",
      campaignType: "manual"
    });
    if (logged) {
      openAppMessageBox("Success", `WhatsApp opened for ${normalizedStudent.name || "student"}.`, "success");
      return true;
    }
    openAppMessageBox("Error", "Unable to open WhatsApp for this student.", "error");
    return false;
  }

  function getGenderPrefix(gender) {
    const normalized = String(gender || "").trim().toLowerCase();
    if (normalized === "male") {
      return "Mr";
    }
    if (normalized === "female") {
      return "Ms";
    }
    return "Mx";
  }

  function getSavedMessageTemplate(key, fallback) {
    if (!database.generalSettings) {
      database.generalSettings = {};
    }
    if (!database.generalSettings.messageTemplates) {
      database.generalSettings.messageTemplates = {};
    }
    return database.generalSettings.messageTemplates[key] || fallback;
  }

  function saveMessageTemplate(key, input) {
    if (!input) {
      return;
    }
    if (!database.generalSettings) {
      database.generalSettings = {};
    }
    if (!database.generalSettings.messageTemplates) {
      database.generalSettings.messageTemplates = {};
    }
    database.generalSettings.messageTemplates[key] = input.value;
    saveDatabase();
  }

  function buildCommunicationTemplate(type, data) {
    const payload = data || {};
    const schoolName = (database && database.school && database.school.name) ? database.school.name : "School";
    if (type === "student-absent") {
      return `Dear student/parent ${payload.prefix || "Mr./Ms."} ${payload.name || "-"} (Roll No: ${payload.rollNo || "-"}), is absent from school today ${payload.date || "-"}. Please contact school office.\nBest regards,\n${schoolName}.`;
    }
    if (type === "employee-absent") {
      return `Dear ${payload.prefix || "Mr./Ms."} ${payload.name || "-"}, you are marked absent today ${payload.date || "-"}. Please contact school office.\nBest regards,\n${schoolName}.`;
    }
    if (type === "homework") {
      return `Dear student/parent ${payload.prefix || "Mr./Ms."} ${payload.rollNo || "-"},\nHomework assigned.\nSubject: ${payload.subject || "-"}\nTitle: ${payload.title || "-"}\nDue Date: ${payload.dueDate || "-"}\nDetails: ${payload.details || "-"}\nBest regards,\n${schoolName}.`;
    }
    if (type === "result") {
      return `Dear student/parent ${payload.prefix || "Mr./Ms."} ${payload.rollNo || "-"},\nResult (${payload.exam || "Exam"}): ${payload.obtained || 0}/${payload.total || 0} (${payload.percent || 0}%), Grade ${payload.grade || "-"}, Status ${payload.status || "-"}.\nBest regards,\n${schoolName}.`;
    }
    if (type === "admission") {
      return `Dear student/parent ${payload.prefix || "Mr./Ms."} ${payload.rollNo || "-"},\nAdmission confirmed in class ${payload.className || "-"} on ${payload.admissionDate || "-"}.\nBest regards,\n${schoolName}.`;
    }
    if (type === "student-report") {
      return `Dear student/parent ${payload.prefix || "Mr./Ms."} ${payload.rollNo || "-"},\nYour report is ready.\nExam: ${payload.exam || "Exam"}\nResult: ${payload.obtained || 0}/${payload.total || 0} (${payload.percent || 0}%)\nGrade: ${payload.grade || "-"}\nStatus: ${payload.status || "-"}\nBest regards,\n${schoolName}.`;
    }
    if (type === "employee-report") {
      return `Dear ${payload.prefix || "Mr./Ms."} ${payload.name || "-"},\nAttendance report for ${payload.month || "-"} is ready.\nPresent: ${payload.present || 0}, Absent: ${payload.absent || 0}, Leave: ${payload.leave || 0}, Attendance: ${payload.percent || 0}%.\nBest regards,\n${schoolName}.`;
    }
    if (type === "fee-reminder") {
      return `Dear student/parent ${payload.prefix || "Mr./Ms."} ${payload.rollNo || "-"},\nFee reminder for ${payload.month || "-"}.\nOutstanding amount: ${payload.amount || 0}.\nPlease submit fee on time.\nBest regards,\n${schoolName}.`;
    }
    return `Dear ${payload.name || "User"},\nThis is an update from ${schoolName}.\nBest regards,\n${schoolName}.`;
  }

