  function pickStudentValue(student, keys, fallback) {
    const item = student || {};
    for (let index = 0; index < keys.length; index += 1) {
      const key = keys[index];
      if (typeof item[key] !== "undefined" && item[key] !== null && String(item[key]).trim() !== "") {
        return item[key];
      }
    }
    return typeof fallback === "undefined" ? "" : fallback;
  }

  function normalizeStudentForPrint(student) {
    return {
      id: pickStudentValue(student, ["id", "studentId"], ""),
      name: String(pickStudentValue(student, ["name", "studentName", "fullName"], "-")),
      picture: String(pickStudentValue(student, ["picture", "photo", "profilePicture", "avatar"], "")),
      admissionNo: String(pickStudentValue(student, ["admissionNo", "rollNo", "registrationNo", "rollNumber"], "-")),
      className: String(pickStudentValue(student, ["className", "class", "classTitle"], "-")),
      section: String(pickStudentValue(student, ["section", "classSection"], "")),
      fatherName: String(pickStudentValue(student, ["fatherName", "guardianName", "father"], "-")),
      phone: String(pickStudentValue(student, ["whatsappNumber", "whatsappNo", "whatsappPhone", "phone", "studentPhone", "mobile", "mobileNo"], "-")),
      status: String(pickStudentValue(student, ["status"], "active")),
      dateOfAdmission: String(pickStudentValue(student, ["dateOfAdmission", "admissionDate"], "-")),
      dateOfBirth: String(pickStudentValue(student, ["dateOfBirth", "dob"], "-")),
      gender: String(pickStudentValue(student, ["gender"], "-")),
      bloodGroup: String(pickStudentValue(student, ["bloodGroup"], "-")),
      diseaseInfo: String(pickStudentValue(student, ["diseaseInfo", "disease"], "-")),
      birthId: String(pickStudentValue(student, ["birthId", "bForm", "nic"], "-")),
      previousSchool: String(pickStudentValue(student, ["previousSchool"], "-")),
      previousId: String(pickStudentValue(student, ["previousId", "previousBoardRollNo"], "-")),
      orphanStatus: String(pickStudentValue(student, ["orphanStatus"], "-")),
      religion: String(pickStudentValue(student, ["religion"], "-")),
      address: String(pickStudentValue(student, ["address", "homeAddress"], "-")),
      fatherEducation: String(pickStudentValue(student, ["fatherEducation"], "-")),
      fatherNationalId: String(pickStudentValue(student, ["fatherNationalId"], "-")),
      fatherPhone: String(pickStudentValue(student, ["fatherPhone", "guardianPhone", "parentPhone"], "-")),
      fatherOccupation: String(pickStudentValue(student, ["fatherOccupation"], "-")),
      fatherIncome: String(pickStudentValue(student, ["fatherIncome"], "-")),
      motherName: String(pickStudentValue(student, ["motherName"], "-")),
      motherEducation: String(pickStudentValue(student, ["motherEducation"], "-")),
      motherNationalId: String(pickStudentValue(student, ["motherNationalId"], "-")),
      motherPhone: String(pickStudentValue(student, ["motherPhone"], "-")),
      motherOccupation: String(pickStudentValue(student, ["motherOccupation"], "-")),
      discountInFee: String(pickStudentValue(student, ["discountInFee"], "-"))
    };
  }

  function normalizeImageForPrintShared(src) {
    return new Promise(function (resolve) {
      if (!src) {
        resolve("");
        return;
      }
      const image = new Image();
      let isSettled = false;
      const done = function (value) {
        if (isSettled) {
          return;
        }
        isSettled = true;
        resolve(value || "");
      };
      image.onload = function () {
        try {
          const canvas = document.createElement("canvas");
          const width = Math.max(1, image.naturalWidth || image.width || 1);
          const height = Math.max(1, image.naturalHeight || image.height || 1);
          canvas.width = width;
          canvas.height = height;
          const ctx = canvas.getContext("2d");
          if (!ctx) {
            done(src);
            return;
          }
          ctx.fillStyle = "#ffffff";
          ctx.fillRect(0, 0, width, height);
          ctx.drawImage(image, 0, 0, width, height);
          done(canvas.toDataURL("image/png", 1));
        } catch (error) {
          done(src);
        }
      };
      image.onerror = function () {
        done(src);
      };
      setTimeout(function () {
        done(src);
      }, 2500);
      image.crossOrigin = "anonymous";
      image.referrerPolicy = "no-referrer";
      image.src = src;
    });
  }

  function waitForPrintResources(printWindow) {
    return new Promise(function (resolve) {
      if (!printWindow || !printWindow.document) {
        resolve();
        return;
      }
      const doc = printWindow.document;
      const images = Array.from(doc.images || []);
      const waits = images.map(function (img) {
        if (img.complete && img.naturalWidth > 0) {
          return Promise.resolve();
        }
        return new Promise(function (done) {
          const finish = function () { done(); };
          img.addEventListener("load", finish, { once: true });
          img.addEventListener("error", finish, { once: true });
        });
      });
      if (doc.fonts && typeof doc.fonts.ready === "object") {
        waits.push(doc.fonts.ready.catch(function (err) { console.warn("Font loading failed:", err); }));
      }
      Promise.race([
        Promise.all(waits),
        new Promise(function (done) { setTimeout(done, 1800); })
      ]).then(function () {
        resolve();
      });
    });
  }

  function sanitizePrintableHtml(input) {
    const html = String(input || "");
    return html
      .replace(/<script[\s\S]*?>[\s\S]*?<\/script>/gi, "")
      .replace(/<style[\s\S]*?>[\s\S]*?<\/style>/gi, "")
      .replace(/\son\w+="[^"]*"/gi, "")
      .replace(/\son\w+='[^']*'/gi, "");
  }

  function showPaperSizeDialog() {
    return new Promise(function (resolve) {
      const result = confirm("A4 size print kren?\n\nOK = A4\nCancel = Thermal");
      resolve(result ? "a4" : "thermal");
    });
  }

