  async function openPrintHtmlWindow(html, popupOptions, popupErrorMessage) {
    if (window.SagarSoftDesktop && typeof window.SagarSoftDesktop.openPrintHtml === "function") {
      await window.SagarSoftDesktop.openPrintHtml({ html: html });
      return;
    }
    const popup = window.open("", "_blank", popupOptions || "width=1200,height=900");
    if (!popup) {
      openAppMessageBox("Error", popupErrorMessage || "Please allow popups to print.", "error");
      return;
    }
    popup.document.write(html);
    popup.document.close();
    popup.focus();
    await waitForPrintResources(popup);
    popup.print();
    var dialogOpened = false;
    var closeTimer = setInterval(function() {
      try {
        if (popup.closed) { clearInterval(closeTimer); return; }
        if (popup.matchMedia('print').matches) dialogOpened = true;
        if (dialogOpened && !popup.matchMedia('print').matches) {
          clearInterval(closeTimer);
          popup.close();
        }
      } catch(e) { clearInterval(closeTimer); }
    }, 200);
  }

  async function openThermalPrintWindow(html, popupOptions, popupErrorMessage) {
    await openPrintHtmlWindow(html, popupOptions || "width=420,height=700", popupErrorMessage || "Please allow popups to print thermal document.");
  }

  function formatStatus(status) {
    return String(status).toLowerCase();
  }

  function setFormMessage(message, type) {
    studentFormMessage.textContent = message;
    studentFormMessage.className = "form-message" + (type ? ` ${type}` : "");
  }

  function getStudentClassOptions() {
    return database.classes.map(function (classItem) {
      return classItem.name;
    });
  }

  function getTeacherOptions() {
    const names = [];

    database.teachers.forEach(function (teacher) {
      if (teacher.name) {
        names.push(teacher.name);
      }
    });

    database.users.forEach(function (user) {
      if (user.role === "teacher" && user.name) {
        names.push(user.name);
      }
    });

    database.classes.forEach(function (classItem) {
      if (classItem.classTeacher) {
        names.push(classItem.classTeacher);
      }
    });

    return Array.from(new Set(names)).sort();
  }

  function renderStudentClassOptions() {
    const classOptions = getStudentClassOptions();
    const teacherOptions = getTeacherOptions();
    const selectedFormClass = studentClassNameInput.value;
    const selectedAllStudentsClass = allStudentsClassFilter.value;
    const selectedAllStudentsGender = allStudentsGenderFilter.value;
    const selectedFilterClass = studentClassFilter.value;
    const selectedStatusClass = studentStatusClassFilter.value;
    const selectedIdCardClass = studentIdCardsClassFilter.value;
    const selectedPrintListClass = printBasicListClassFilter.value;
    const selectedPromoteClass = promoteStudentsClassFilter.value;
    const selectedPromoteTargetClass = promoteTargetClassSelect.value;
    const selectedClassTeacher = newClassTeacherInput.value;
    const selectedAssignSubjectClass = assignSubjectsClassInput.value;
    const optionsMarkup = classOptions.map(function (className) {
      return `<option value="${className}">${className}</option>`;
    }).join("");
    const teacherOptionsMarkup = teacherOptions.map(function (teacherName) {
      return `<option value="${teacherName}">${teacherName}</option>`;
    }).join("");

    studentClassNameInput.innerHTML = optionsMarkup;
    allStudentsClassFilter.innerHTML = `<option value="all">All Classes</option>${optionsMarkup}`;
    studentClassFilter.innerHTML = `<option value="all">All Classes</option>${optionsMarkup}`;
    studentStatusClassFilter.innerHTML = `<option value="all">All Classes</option>${optionsMarkup}`;
    studentIdCardsClassFilter.innerHTML = `<option value="all">All Classes</option>${optionsMarkup}`;
    printBasicListClassFilter.innerHTML = `<option value="all">All Classes</option>${optionsMarkup}`;
    promoteStudentsClassFilter.innerHTML = `<option value="all">All Classes</option>${optionsMarkup}`;
    promoteTargetClassSelect.innerHTML = `<option value="">Select Target Class</option>${optionsMarkup}`;
    newClassTeacherInput.innerHTML = `<option value="">Select</option>${teacherOptionsMarkup}`;
    assignSubjectsClassInput.innerHTML = `<option value="">Select*</option>${optionsMarkup}`;

    studentClassNameInput.value = classOptions.includes(selectedFormClass) ? selectedFormClass : (classOptions[0] || "");
    allStudentsClassFilter.value = selectedAllStudentsClass === "all" || classOptions.includes(selectedAllStudentsClass)
      ? selectedAllStudentsClass
      : "all";
    allStudentsGenderFilter.value = ["all", "Male", "Female"].includes(selectedAllStudentsGender)
      ? selectedAllStudentsGender
      : "all";
    studentClassFilter.value = selectedFilterClass === "all" || classOptions.includes(selectedFilterClass)
      ? selectedFilterClass
      : "all";
    studentStatusClassFilter.value = selectedStatusClass === "all" || classOptions.includes(selectedStatusClass)
      ? selectedStatusClass
      : "all";
    studentIdCardsClassFilter.value = selectedIdCardClass === "all" || classOptions.includes(selectedIdCardClass)
      ? selectedIdCardClass
      : "all";
    printBasicListClassFilter.value = selectedPrintListClass === "all" || classOptions.includes(selectedPrintListClass)
      ? selectedPrintListClass
      : "all";
    promoteStudentsClassFilter.value = selectedPromoteClass === "all" || classOptions.includes(selectedPromoteClass)
      ? selectedPromoteClass
      : "all";
    promoteTargetClassSelect.value = selectedPromoteTargetClass && classOptions.includes(selectedPromoteTargetClass)
      ? selectedPromoteTargetClass
      : "";
    newClassTeacherInput.value = teacherOptions.includes(selectedClassTeacher)
      ? selectedClassTeacher
      : "";
    assignSubjectsClassInput.value = selectedAssignSubjectClass && classOptions.includes(selectedAssignSubjectClass)
      ? selectedAssignSubjectClass
      : "";
  }

  function getClassStudents(className) {
    return database.students.filter(function (student) {
      return student.className === className && student.status === "active";
    });
  }

  function getGenderCount(students, gender) {
    return students.filter(function (student) {
      return String(student.gender || "").toLowerCase() === gender.toLowerCase();
    }).length;
  }

  function getPercentage(count, total) {
    if (!total) {
      return 0;
    }
    return Math.round((count / total) * 100);
  }

  function populateClassForm(classItem) {
    if (!classItem) {
      newClassIdInput.value = "";
      newClassNameInput.value = "";
      newClassSectionInput.value = "";
      newClassMonthlyFeeInput.value = "";
      newClassTeacherInput.value = "";
      newClassTitle.textContent = "Create New Class";
      setClassMessage("", "");
      return;
    }

    var pipeIdx = classItem.name.lastIndexOf(" | ");
    if (pipeIdx > 0) {
      newClassNameInput.value = classItem.name.slice(0, pipeIdx);
      newClassSectionInput.value = classItem.name.slice(pipeIdx + 3);
    } else {
      newClassNameInput.value = classItem.name || "";
      newClassSectionInput.value = "";
    }
    newClassIdInput.value = classItem.id;
    newClassMonthlyFeeInput.value = classItem.monthlyTuitionFees || "";
    newClassTeacherInput.value = classItem.classTeacher || "";
    newClassTitle.textContent = `Edit ${classItem.name}`;
    setClassMessage("Editing selected class.", "success");
  }

  function renderAllClassesTable() {
    const cards = database.classes.map(function (classItem) {
      const classStudents = getClassStudents(classItem.name);
      const totalStudents = classStudents.length;
      const boysCount = getGenderCount(classStudents, "Male");
      const girlsCount = getGenderCount(classStudents, "Female");
      const boysPercentage = getPercentage(boysCount, totalStudents);
      const girlsPercentage = getPercentage(girlsCount, totalStudents);

      return `
        <div class="stat-card class-card" data-class-id="${classItem.id}">
          <div class="class-card__header">
            <h4>${classItem.name}</h4>
            <div class="class-card__actions">
              <button class="table-action-btn" type="button" data-action="edit-class" data-id="${classItem.id}">Edit</button>
              <button class="table-action-btn danger" type="button" data-action="delete-class" data-id="${classItem.id}">Delete</button>
            </div>
          </div>
          <div class="class-card__stats">
            <div class="stat-item">
              <span class="stat-label">Total Students</span>
              <span class="stat-value">${totalStudents}</span>
            </div>
            <div class="stat-item">
              <span class="stat-label">Boys</span>
              <button class="stat-link" type="button" data-action="class-view-boys" data-id="${classItem.id}">
                ${boysCount} (${boysPercentage}%)
              </button>
            </div>
            <div class="stat-item">
              <span class="stat-label">Girls</span>
              <button class="stat-link" type="button" data-action="class-view-girls" data-id="${classItem.id}">
                ${girlsCount} (${girlsPercentage}%)
              </button>
            </div>
          </div>
        </div>
      `;
    }).join("");

    allClassesContainer.innerHTML = cards;
    allClassesEmptyState.hidden = database.classes.length !== 0;
  }

  function generateClassId() {
    return `CLS-${Date.now()}`;
  }

  function handleClassFormSubmit(event) {
    event.preventDefault();

    const classId = newClassIdInput.value;
    const baseName = newClassNameInput.value.trim();
    const classSection = newClassSectionInput.value.trim();
    const monthlyTuitionFees = newClassMonthlyFeeInput.value.trim();
    const classTeacher = newClassTeacherInput.value;
    if (!baseName || !classSection || !monthlyTuitionFees || !classTeacher) {
      setClassMessage("Please fill Class Name, Section, Monthly Tuition Fees, and Select Class Teacher.", "error");
      return;
    }

    const fullName = baseName + " | " + classSection;

    const existingIndex = database.classes.findIndex(function (classItem) {
      return classItem.id === classId;
    });

    if (existingIndex >= 0) {
      const oldClassName = database.classes[existingIndex].name;
      database.classes[existingIndex] = {
        ...database.classes[existingIndex],
        name: fullName,
        monthlyTuitionFees: Number(monthlyTuitionFees),
        classTeacher: classTeacher
      };

      if (oldClassName !== fullName) {
        database.students = database.students.map(function (student) {
          if (student.className === oldClassName) {
            return { ...student, className: fullName };
          }
          return student;
        });
      }

      addActivity("Class updated", `${fullName} was updated.`);
      setClassMessage("Class updated successfully.", "success");
      setAllClassesMessage("Class updated successfully.", "success");
    } else {
      database.classes.unshift({
        id: generateClassId(),
        name: fullName,
        monthlyTuitionFees: Number(monthlyTuitionFees),
        classTeacher: classTeacher
      });
      addActivity("Class created", `${fullName} was added with class teacher ${classTeacher}.`);
      setClassMessage("Class created successfully.", "success");
      setAllClassesMessage("Class created successfully.", "success");
    }

    saveDatabase();
    refreshDatabase();
    renderDashboard();
    renderAllClassesTable();
    populateClassForm(null);
    setStudentRoute("all-classes");
  }

  function getClassSubjects(className) {
    return database.subjects.filter(function (subject) {
      return subject.className === className;
    });
  }

  function getTotalExamMarks(subjects) {
    return subjects.reduce(function (sum, subject) {
      return sum + Number(subject.marks || 0);
    }, 0);
  }

  function createSubjectRow(rowData) {
    const row = document.createElement("div");
    row.className = "subject-row";
    row.innerHTML = `
      <div class="field-group">
        <label>Subject Name*</label>
        <input type="text" class="subject-name-input" placeholder="e.g English" required>
      </div>
      <div class="field-group">
        <label>Marks*</label>
        <input type="number" min="1" class="subject-marks-input" placeholder="e.g 100" required>
      </div>
    `;

    if (rowData && rowData.name) {
      row.querySelector(".subject-name-input").value = rowData.name;
    }

    if (rowData && rowData.marks) {
      row.querySelector(".subject-marks-input").value = rowData.marks;
    }

    return row;
  }

  function ensureSubjectRowExists() {
    if (assignSubjectsRows.children.length === 0) {
      assignSubjectsRows.appendChild(createSubjectRow());
    }
  }

  function getAssignSubjectRowsData() {
    return Array.from(assignSubjectsRows.querySelectorAll(".subject-row")).map(function (row) {
      const nameInput = row.querySelector(".subject-name-input");
      const marksInput = row.querySelector(".subject-marks-input");
      return {
        name: nameInput ? nameInput.value.trim() : "",
        marks: marksInput ? marksInput.value.trim() : ""
      };
    });
  }

  function populateAssignSubjectsForm(className) {
    assignSubjectsRows.innerHTML = "";
    setAssignSubjectsMessage("", "");
    if (className) {
      assignSubjectsClassInput.value = className;
    }

    const selectedClass = className || assignSubjectsClassInput.value;
    const classSubjects = selectedClass ? getClassSubjects(selectedClass) : [];

    if (classSubjects.length > 0) {
      classSubjects.forEach(function (subject) {
        assignSubjectsRows.appendChild(createSubjectRow({ name: subject.name, marks: subject.marks }));
      });
    } else {
      assignSubjectsRows.appendChild(createSubjectRow());
    }

    assignSubjectsTitle.textContent = "Assign Subjects";
  }

  function renderClassesWithSubjects() {
    const classCards = database.classes.map(function (classItem) {
      const classStudents = getClassStudents(classItem.name);
      const classSubjects = getClassSubjects(classItem.name);
      const totalStudents = classStudents.length;
      const totalSubjects = classSubjects.length;
      const totalExamMarks = getTotalExamMarks(classSubjects);
      const subjectRowsMarkup = classSubjects.length
        ? classSubjects.map(function (subject) {
          return `
            <article>
              <strong>${subject.name || "-"}</strong>
              <span>Marks: ${Number(subject.marks || 0)}</span>
            </article>
          `;
        }).join("")
        : `<article><strong>No subjects assigned yet</strong><span>Use Assign Subjects to add.</span></article>`;

      return `
        <article class="class-subject-card">
          <div class="class-subject-card__head">
            <div>
              <h4>${classItem.name}</h4>
              <p>Total Students: ${totalStudents}</p>
            </div>
            <button class="table-action-btn" type="button" data-action="edit-class-subjects" data-class="${classItem.name}">Edit</button>
          </div>
          <div class="subject-meta-grid">
            <article class="subject-meta-item">
              <strong>${totalSubjects}</strong>
              <span>Total Subjects</span>
            </article>
            <article class="subject-meta-item">
              <strong>${totalExamMarks}</strong>
              <span>Total Exam Marks</span>
            </article>
            <article class="subject-meta-item">
              <strong>${classItem.classTeacher || "-"}</strong>
              <span>Class Teacher</span>
            </article>
          </div>
          <div class="subject-list">${subjectRowsMarkup}</div>
        </article>
      `;
    }).join("");

    classesWithSubjectsGrid.innerHTML = classCards;
    classesWithSubjectsEmptyState.hidden = database.classes.length !== 0;
  }

  function handleAssignSubjectsSubmit(event) {
    event.preventDefault();
    const selectedClass = assignSubjectsClassInput.value;
    const rows = getAssignSubjectRowsData();

    if (!selectedClass) {
      setAssignSubjectsMessage("Please select class first.", "error");
      return;
    }

    const invalidRow = rows.find(function (row) {
      return !row.name || !row.marks;
    });

    if (invalidRow) {
      setAssignSubjectsMessage("Please fill Subject Name and Marks in all rows.", "error");
      return;
    }

    const duplicateSubject = rows.find(function (row, index) {
      return rows.findIndex(function (compareRow) {
        return compareRow.name.toLowerCase() === row.name.toLowerCase();
      }) !== index;
    });

    if (duplicateSubject) {
      setAssignSubjectsMessage("Duplicate subject names found. Use unique subject names.", "error");
      return;
    }

    database.subjects = database.subjects.filter(function (subject) {
      return subject.className !== selectedClass;
    });

    rows.forEach(function (row, index) {
      database.subjects.push({
        id: `SUB-${Date.now()}-${index}`,
        className: selectedClass,
        name: row.name,
        marks: Number(row.marks)
      });
    });

    addActivity("Subjects assigned", `${rows.length} subjects assigned to ${selectedClass}.`);
    saveDatabase();
    refreshDatabase();
    renderDashboard();
    setAssignSubjectsMessage("Subjects assigned successfully.", "success");
    setClassesWithSubjectsMessage("Subjects updated successfully.", "success");
    setStudentRoute("classes-with-subjects");
  }

  function handleClassesWithSubjectsClick(event) {
    const button = event.target.closest("[data-action='edit-class-subjects']");
    if (!button) {
      return;
    }

    const className = button.dataset.class;
    if (!className) {
      return;
    }

    setRoute("assign-subjects");
    assignSubjectsClassInput.value = className;
    populateAssignSubjectsForm(className);
  }

