  function readStudentPicture(file) {
    return new Promise(function (resolve, reject) {
      if (!file) {
        resolve(currentStudentPicture);
        return;
      }

      if (file.size > 102400) {
        reject(new Error("Picture size must be 100KB or less."));
        return;
      }

      const reader = new FileReader();
      reader.onload = function () {
        resolve(reader.result);
      };
      reader.onerror = function () {
        reject(new Error("Unable to read selected picture."));
      };
      reader.readAsDataURL(file);
    });
  }

  function getFilteredStudents() {
    const search = studentSearchInput.value.trim().toLowerCase();
    const classFilter = studentClassFilter.value;
    const statusFilter = studentStatusFilter.value;

    return getNormalizedStudentsDataset().filter(function (student) {
      const matchesSearch =
        !search ||
        student.name.toLowerCase().includes(search) ||
        String(student.admissionNo || "").toLowerCase().includes(search) ||
        student.className.toLowerCase().includes(search);

      const matchesClass = classFilter === "all" || student.className === classFilter;
      const matchesStatus = statusFilter === "all" || student.status === statusFilter;

      return matchesSearch && matchesClass && matchesStatus;
    });
  }

  function getDirectoryStudents() {
    const search = allStudentsSearchInput.value.trim().toLowerCase();
    const classFilter = allStudentsClassFilter.value;
    const genderFilter = allStudentsGenderFilter.value;

    return getNormalizedStudentsDataset().filter(function (student) {
      const isEnrolled = student.status === "active";
      const matchesSearch =
        !search ||
        student.name.toLowerCase().includes(search) ||
        String(student.admissionNo || "").toLowerCase().includes(search);
      const matchesClass = classFilter === "all" || student.className === classFilter;
      const matchesGender = genderFilter === "all" || String(student.gender || "").toLowerCase() === genderFilter.toLowerCase();

      return isEnrolled && matchesSearch && matchesClass && matchesGender;
    });
  }

