  function getStudentLoginInfo(student) {
    const safeStudent = student || {};
    const users = Array.isArray(database.users) ? database.users : [];
    const studentId = String(safeStudent.id || "");
    const studentName = String(safeStudent.name || "");
    const admissionText = String(safeStudent.admissionNo || "");
    const loginUser = users.find(function (user) {
      return user && user.role === "student" && (user.id === `LOGIN-${studentId}` || user.name === studentName);
    });

    if (loginUser) {
      return {
        status: loginUser.active ? "Active" : "Inactive",
        username: loginUser.email || "-",
        password: loginUser.password || "-"
      };
    }

    const normalizedAdmission = admissionText ? admissionText.toLowerCase() : "";
    const derivedUsername = normalizedAdmission ? `${normalizedAdmission}@student.local` : "-";
    const derivedPassword = normalizedAdmission ? `${normalizedAdmission}123` : "-";
    return {
      status: "Not Created",
      username: derivedUsername,
      password: derivedPassword
    };
  }

  function getEmployees() {
    return (database.teachers || []).map(function (employee) {
      return {
        ...employee,
        designation: employee.designation || employee.role || "Teacher",
        role: employee.role || "Teacher",
        dateOfJoining: employee.dateOfJoining || "",
        monthlySalary: Number(employee.monthlySalary || 0),
        phone: employee.phone || "",
        picture: employee.picture || "",
        fatherOrHusbandName: employee.fatherOrHusbandName || "",
        nationalId: employee.nationalId || "",
        education: employee.education || "",
        gender: employee.gender || "",
        religion: employee.religion || "",
        bloodGroup: employee.bloodGroup || "",
        experience: employee.experience || "",
        email: employee.email || "",
        dateOfBirth: employee.dateOfBirth || "",
        address: employee.address || "",
        status: employee.status || "active"
      };
    });
  }

  function getEmployeeById(employeeId) {
    const targetId = String(employeeId || "");
    return getEmployees().find(function (employee) {
      return String(employee.id || "") === targetId;
    }) || null;
  }

  function getEmployeeLoginInfo(employee) {
    const loginUser = database.users.find(function (user) {
      return user.role === "teacher" && (user.employeeId === employee.id || user.name === employee.name);
    });

    if (loginUser) {
      return {
        status: loginUser.active ? "Active" : "Inactive",
        username: loginUser.email || "-",
        password: loginUser.password || "-"
      };
    }

    const baseName = String(employee.name || "employee").toLowerCase().replace(/\s+/g, ".");
    return {
      status: "Not Created",
      username: `${baseName}@employee.local`,
      password: `${baseName.replace(/\./g, "")}123`
    };
  }

  function saveEmployeeRecord(employeeRecord) {
    const existingIndex = database.teachers.findIndex(function (employee) {
      return employee.id === employeeRecord.id;
    });

    if (existingIndex >= 0) {
      database.teachers[existingIndex] = employeeRecord;
    } else {
      database.teachers.unshift(employeeRecord);
    }
  }

  function deleteEmployeeRecord(employeeId) {
    const employee = getEmployeeById(employeeId);
    if (!employee) {
      return;
    }
    database.teachers = database.teachers.filter(function (item) {
      return item.id !== employeeId;
    });
    database.users = database.users.filter(function (user) {
      return !(user.role === "teacher" && (user.employeeId === employeeId || user.name === employee.name));
    });
    addActivity("Employee deleted", `${employee.name} record was removed.`);
    saveDatabase();
  }

  function ensureEmployeeLogin(employee) {
    const existingUserIndex = database.users.findIndex(function (user) {
      return user.role === "teacher" && (user.employeeId === employee.id || user.name === employee.name);
    });
    const fallback = getEmployeeLoginInfo(employee);

    const loginUser = {
      id: existingUserIndex >= 0 ? database.users[existingUserIndex].id : `EMP-LOGIN-${employee.id}`,
      name: employee.name,
      email: fallback.username,
      password: fallback.password,
      role: "teacher",
      employeeId: employee.id,
      phone: employee.phone || "",
      active: employee.status === "active"
    };

    if (existingUserIndex >= 0) {
      database.users[existingUserIndex] = { ...database.users[existingUserIndex], ...loginUser };
    } else {
      database.users.push(loginUser);
    }
  }

  function getTodayDateISO() {
    const today = new Date();
    return today.getFullYear() + "-" + String(today.getMonth() + 1).padStart(2, "0") + "-" + String(today.getDate()).padStart(2, "0");
  }

  function getCurrentMonthYearISO() {
    const today = new Date();
    return today.getFullYear() + "-" + String(today.getMonth() + 1).padStart(2, "0");
  }

  function renderStats() {
    const statsGrid = document.getElementById("statsGrid");
    const settings = (database && database.generalSettings) ? database.generalSettings : {};
    const safeAttr = function (value) {
      return String(value == null ? "" : value).replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    };
    
    // Fees card must follow actual collections and total enrolled students.
    const totalEnrolledStudents = Array.isArray(database.students) ? database.students.length : 0;
    const paidStudentIds = new Set(
      (database.fees || [])
        .filter(function (fee) {
          return fee.status === "paid" && Number(fee.remaining || 0) === 0;
        })
        .map(function (fee) {
          return String(fee.studentId || "").trim();
        })
        .filter(Boolean)
    );
    const paidStudentsCount = paidStudentIds.size;
    
    // Get attendance for TODAY only
    const todayISO = getTodayDateISO();
    const studentAttendance = database.attendance.filter(function (item) {
      const attendanceDate = (item.date || "").substring(0, 10);
      return (item.studentId || !item.entityType || item.entityType === "student") && attendanceDate === todayISO;
    });
    const presentAttendance = studentAttendance.filter(function (item) { return item.status === "Present"; }).length;
    const presentOnLeaveAttendance = studentAttendance.filter(function (item) { return item.status === "Present" || item.status === "On-leave"; }).length;
    const totalStudents = database.students.filter(function (item) { return item.status === "active"; }).length;
    const attendancePercentage = totalStudents > 0 ? Math.round((presentOnLeaveAttendance / totalStudents) * 100) : 0;

    // Get monthly fees breakdown (all months with records)
    const feesByMonth = {};
    database.fees.forEach(function (item) {
      const feeMonth = item.feeMonth || item.month || "Unknown";
      if (!feesByMonth[feeMonth]) {
        feesByMonth[feeMonth] = { total: 0, paid: 0 };
      }
      feesByMonth[feeMonth].total += 1;
      if (item.status === "paid") {
        feesByMonth[feeMonth].paid += 1;
      }
    });
    const monthlyFeesSummary = Object.keys(feesByMonth).length > 0 
      ? `${Object.keys(feesByMonth).reduce(function(sum, m) { return sum + feesByMonth[m].paid; }, 0)} paid in ${Object.keys(feesByMonth).length} months`
      : "No fee records";

    const validClassNames = new Set((database.classes || []).map(function (classItem) {
      return String(classItem.name || "").trim();
    }).filter(Boolean));
    const linkedSubjectsCount = (database.subjects || []).filter(function (subject) {
      const className = String(subject.className || "").trim();
      return className && validClassNames.has(className);
    }).length;

    const cards = [
      {
        icon: "ST",
        tone: "students",
        route: "all-students",
        label: "Students",
        value: database.students.length,
        note: `${totalStudents} active records`
      },
      {
        icon: "TC",
        tone: "teachers",
        route: "all-employees",
        label: "Teachers",
        value: database.teachers.length,
        note: `${linkedSubjectsCount} subjects assigned`
      },
      {
        icon: "CL",
        tone: "classes",
        route: "all-classes",
        label: "Classes",
        value: database.classes.length,
        note: `${database.classes.length} academic groups`
      },
      {
        icon: "FS",
        tone: "fees",
        route: "generate-fees-invoice",
        label: "Fees",
        value: `${paidStudentsCount}/${totalEnrolledStudents}`,
        note: "Paid students / enrolled"
      },
      {
        icon: "AT",
        tone: "attendance",
        route: "students-attendance",
        label: "Attendance",
        value: `${presentAttendance}/${studentAttendance.length}`,
        note: "Today's attendance"
      },
      {
        icon: "PA",
        tone: "parents",
        route: "parents-info-report",
        label: "Parents",
        value: (function () {
          var phones = new Set();
          (database.students || []).forEach(function (s) {
            if (s.fatherPhone) phones.add(s.fatherPhone);
            if (s.motherPhone) phones.add(s.motherPhone);
          });
          return phones.size;
        })(),
        note: "Associated with students"
      },
      {
        icon: "SB",
        tone: "subjects",
        route: "classes-with-subjects",
        label: "Subjects",
        value: linkedSubjectsCount,
        note: "Linked subjects configured"
      },
      {
        icon: "LG",
        tone: "activity",
        route: "students-info-report",
        label: "Activity",
        value: database.activityLogs.length,
        note: "System events stored"
      }
    ];

    statsGrid.innerHTML = cards.map(function (card) {
      return `
        <article class="stat-card dashboard-stat-card dashboard-stat-card--${safeAttr(card.tone || "default")}" data-dashboard-route="${safeAttr(card.route || "")}" role="button" tabindex="0">
          <div class="stat-card__top">
            <div>
              <p class="panel-label">${card.label}</p>
              <strong>${card.value}</strong>
            </div>
            <span class="menu-icon">${card.icon}</span>
          </div>
          <span class="metric-note">${card.note}</span>
        </article>
      `;
    }).join("");
  }

  function handleDashboardCardNavigation(event) {
    const card = event.target.closest("[data-dashboard-route]");
    if (!card) {
      return;
    }
    const route = card.getAttribute("data-dashboard-route");
    if (!route) {
      return;
    }
    setRoute(route);
  }

  function renderStudentStats() {
    const activeCount = database.students.filter(function (student) { return student.status === "active"; }).length;
    const inactiveCount = database.students.filter(function (student) { return student.status === "inactive"; }).length;
    const classCount = new Set(database.students.map(function (student) { return student.className; })).size;
    const filteredCount = getFilteredStudents().length;

    const cards = [
      { label: "Total Students", value: database.students.length, note: "All student records" },
      { label: "Active", value: activeCount, note: "Currently active students" },
      { label: "Inactive", value: inactiveCount, note: "Inactive student records" },
      { label: "Filtered Results", value: filteredCount, note: `${classCount} classes covered` }
    ];

    studentStatsGrid.innerHTML = cards.map(function (card, index) {
      return `
        <article class="stat-card">
          <div class="stat-card__top">
            <div>
              <p class="panel-label">${card.label}</p>
              <strong>${card.value}</strong>
            </div>
            <span class="menu-icon">S${index + 1}</span>
          </div>
          <span class="metric-note">${card.note}</span>
        </article>
      `;
    }).join("");
  }

  function renderActivity() {
    const activityList = document.getElementById("activityList");
    activityList.innerHTML = database.activityLogs.slice(0, 5).map(function (item) {
      const date = new Date(item.createdAt);
      return `
        <article class="activity-item">
          <strong>${item.title}</strong>
          <p>${item.description}</p>
          <time>${date.toLocaleDateString()} ${date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</time>
        </article>
      `;
    }).join("");
  }

  function renderStudentActivity() {
    const items = database.activityLogs.filter(function (item) {
      return item.title.toLowerCase().includes("student");
    }).slice(0, 5);

    studentsActivityList.innerHTML = (items.length ? items : database.activityLogs.slice(0, 3)).map(function (item) {
      return `
        <article class="activity-item">
          <strong>${item.title}</strong>
          <p>${item.description}</p>
        </article>
      `;
    }).join("");
  }

  function getMonthKeyFromValue(value) {
    const raw = String(value || "").trim();
    if (!raw) {
      return "";
    }
    const isoMatch = raw.match(/^(\d{4})-(\d{2})/);
    if (isoMatch) {
      return `${isoMatch[1]}-${isoMatch[2]}`;
    }
    const parsed = new Date(raw);
    if (!Number.isNaN(parsed.getTime())) {
      return `${parsed.getFullYear()}-${String(parsed.getMonth() + 1).padStart(2, "0")}`;
    }
    const monthNames = {
      january: "01", jan: "01",
      february: "02", feb: "02",
      march: "03", mar: "03",
      april: "04", apr: "04",
      may: "05",
      june: "06", jun: "06",
      july: "07", jul: "07",
      august: "08", aug: "08",
      september: "09", sep: "09",
      october: "10", oct: "10",
      november: "11", nov: "11",
      december: "12", dec: "12"
    };
    const labelMatch = raw.toLowerCase().match(/([a-z]+)\s+(\d{4})/);
    if (labelMatch && monthNames[labelMatch[1]]) {
      return `${labelMatch[2]}-${monthNames[labelMatch[1]]}`;
    }
    return "";
  }

  function purgeUntouchedLegacyFinanceData(settings) {
    if (!settings) {
      return false;
    }
    let changed = false;
    settings.accountsLedger = Array.isArray(settings.accountsLedger) ? settings.accountsLedger : [];
    settings.salaryPayments = Array.isArray(settings.salaryPayments) ? settings.salaryPayments : [];

    if (!settings.__accountsLedgerUserTouched && settings.accountsLedger.length) {
      settings.__accountsLedgerUserTouched = true;
      settings.__accountsLedgerLegacyClearedV1 = true;
      settings.__accountsLedgerLegacyClearedV2 = true;
      changed = true;
    }

    if (!settings.__salaryPaymentsUserTouched && settings.salaryPayments.length) {
      settings.salaryPayments = [];
      settings.__salaryPaymentsLegacyClearedV1 = true;
      changed = true;
    }

    return changed;
  }

  function getDashboardMonthFinance() {
    const currentMonth = getCurrentMonthYearISO();
    const settings = (database && database.generalSettings) ? database.generalSettings : {};
    if (purgeUntouchedLegacyFinanceData(settings)) {
      saveDatabase();
    }
    const feeCollections = Array.isArray(settings.feeCollections) ? settings.feeCollections : [];
    const salaryPayments = Array.isArray(settings.salaryPayments) ? settings.salaryPayments : [];
    const accountsLedger = Array.isArray(settings.accountsLedger) ? settings.accountsLedger : [];
    const totalFeeCollection = feeCollections.filter(function (item) {
      return getMonthKeyFromValue(item.collectedAt || item.paymentDate || item.date || item.feeMonth || item.month) === currentMonth;
    }).reduce(function (sum, item) {
      return sum + Number(item.deposit || 0);
    }, 0);
    const totalSalaries = salaryPayments.filter(function (item) {
      return getMonthKeyFromValue(item.paymentDate || item.date || item.salaryMonth || item.createdAt) === currentMonth;
    }).reduce(function (sum, item) {
      return sum + Number(item.netSalary || item.salaryAmount || 0);
    }, 0);
    let monthlyLedger = accountsLedger.filter(function (item) {
      const itemMonth = getMonthKeyFromValue(item.date || item.createdAt);
      return itemMonth ? itemMonth === currentMonth : true;
    });
    if (!monthlyLedger.length && accountsLedger.length) {
      monthlyLedger = accountsLedger.slice();
    }
    const totalIncome = monthlyLedger.filter(function (item) {
      return String(item.type || "").toLowerCase() === "income";
    }).reduce(function (sum, item) {
      return sum + Number(item.amount || 0);
    }, 0);
    const totalExpenses = monthlyLedger.filter(function (item) {
      return String(item.type || "").toLowerCase() === "expense";
    }).reduce(function (sum, item) {
      return sum + Number(item.amount || 0);
    }, 0);
    return {
      currentMonth: currentMonth,
      totalFeeCollection: totalFeeCollection,
      totalIncome: totalIncome,
      totalSalaries: totalSalaries,
      totalExpenses: totalExpenses,
      incomeTotal: totalFeeCollection + totalIncome,
      expenseTotal: totalSalaries + totalExpenses,
      totalProfit: (totalFeeCollection + totalIncome) - totalSalaries - totalExpenses
    };
  }

  function renderInsights() {
    const insightList = document.getElementById("insightList");
    const currentMonth = getCurrentMonthYearISO();
    const finance = getDashboardMonthFinance();
    const unpaidCount = database.fees.filter(function (item) {
      const statusOk = item.status === "unpaid" || Number(item.remaining || 0) > 0;
      const monthOk = !item.feeMonth && !item.month ? true : getMonthKeyFromValue(item.feeMonth || item.month || item.date || item.paymentDate) === currentMonth;
      return statusOk && monthOk;
    }).length;
    const absentCount = database.attendance.filter(function (item) {
      const isStudentAttendance = item.studentId || !item.entityType || item.entityType === "student";
      const dateOk = !item.date || String(item.date).slice(0, 10) === getTodayDateISO();
      return isStudentAttendance && item.status === "Absent" && dateOk;
    }).length;
    const inactiveStudents = database.students.filter(function (item) { return item.status === "inactive"; }).length;

    const insights = [];
    if (unpaidCount > 0) {
      insights.push({
        badge: "FN",
        title: `${unpaidCount} unpaid fee record${unpaidCount === 1 ? "" : "s"} this month`,
        text: "Open Fees Defaulters to follow up pending payments.",
        route: "fees-defaulters"
      });
    }
    if (absentCount > 0) {
      insights.push({
        badge: "AT",
        title: `${absentCount} student absence${absentCount === 1 ? "" : "s"} today`,
        text: "Open Students Attendance Report to review attendance.",
        route: "students-attendance-report"
      });
    }
    if (inactiveStudents > 0) {
      insights.push({
        badge: "SR",
        title: `${inactiveStudents} inactive student profile${inactiveStudents === 1 ? "" : "s"}`,
        text: "Open Active / Inactive Students to review records.",
        route: "students-active-inactive"
      });
    }
    if (finance.totalFeeCollection || finance.totalIncome || finance.totalSalaries || finance.totalExpenses) {
      insights.push({
        badge: "PF",
        title: `Monthly profit snapshot: ${finance.totalProfit}`,
        text: "Open Accounts Report to review income, fees, salary and expenses.",
        route: "accounts-report"
      });
    }

    if (!insights.length) {
      insightList.innerHTML = `
        <article class="insight-item">
          <span class="insight-item__badge icon-button">OK</span>
          <div>
            <strong>No urgent insights right now</strong>
            <p>Fees, attendance, students and accounts will appear here when there is actionable data.</p>
          </div>
        </article>
      `;
      return;
    }

    insightList.innerHTML = insights.map(function (item) {
      return `
        <article class="insight-item" data-insight-route="${escapeAttr(item.route || "dashboard")}" style="cursor:pointer;">
          <span class="insight-item__badge icon-button">${item.badge}</span>
          <div>
            <strong>${item.title}</strong>
            <p>${item.text}</p>
          </div>
        </article>
      `;
    }).join("");
    insightList.querySelectorAll("[data-insight-route]").forEach(function (item) {
      item.addEventListener("click", function () {
        setRoute(item.getAttribute("data-insight-route") || "dashboard");
      });
    });
  }

