  function renderAdmissionLetterDetail(student) {
    if (!student) {
      admissionLetterDetail.innerHTML = `
        <article>
          <strong>Select a student</strong>
          <p>Search by roll number or name and click Select to load admission details.</p>
        </article>
      `;
      printAdmissionLetterBtn.disabled = true;
      if (sendAdmissionMessageBtn) {
        sendAdmissionMessageBtn.disabled = true;
      }
      if (sendAdmissionWhatsappBtn) {
        sendAdmissionWhatsappBtn.disabled = true;
      }
      return;
    }

    const loginInfo = getStudentLoginInfo(student);
    const profileMedia = student.picture
      ? `<img src="${student.picture}" alt="${student.name}" class="student-avatar student-avatar--image">`
      : `<span class="student-avatar">${getInitials(student.name)}</span>`;

    admissionLetterDetail.innerHTML = `
      <article>
        <div class="admission-profile">
          ${profileMedia}
          <div>
            <strong>${student.name}</strong>
            <p>Roll Number: ${student.admissionNo || "-"}</p>
          </div>
        </div>
        <div class="admission-grid">
          <div class="admission-field"><strong>Roll Number</strong><span>${student.admissionNo || "-"}</span></div>
          <div class="admission-field"><strong>Class</strong><span>${student.className || "-"}</span></div>
          <div class="admission-field"><strong>Admission Date</strong><span>${student.dateOfAdmission || "-"}</span></div>
          <div class="admission-field"><strong>Account Status</strong><span>${loginInfo.status}</span></div>
          <div class="admission-field"><strong>Username</strong><span>${loginInfo.username}</span></div>
          <div class="admission-field"><strong>Password</strong><span>${loginInfo.password}</span></div>
        </div>
        <div class="form-grid" style="margin-top:0.9rem;">
          <div class="field-group">
            <label for="admissionMessageChannelSelect">Channel</label>
            <select id="admissionMessageChannelSelect">
              <option value="sms">SMS</option>
              <option value="whatsapp">WhatsApp</option>
            </select>
          </div>
          </div>
      </article>
    `;

    printAdmissionLetterBtn.disabled = false;
    if (sendAdmissionMessageBtn) {
      sendAdmissionMessageBtn.disabled = false;
    }
    if (sendAdmissionWhatsappBtn) {
      sendAdmissionWhatsappBtn.disabled = false;
    }
  }

  function renderAdmissionLetterStudents() {
    const students = getAdmissionSearchStudents();

    if (!selectedAdmissionStudentId && students.length > 0) {
      selectedAdmissionStudentId = students[0].id;
    }

    if (selectedAdmissionStudentId && !students.some(function (student) { return student.id === selectedAdmissionStudentId; })) {
      selectedAdmissionStudentId = students[0] ? students[0].id : null;
    }

    admissionLetterStudentList.innerHTML = students.map(function (student) {
      return `
        <article>
          <div>
            <strong>${student.name}</strong>
            <span>${student.admissionNo || "-"}</span>
          </div>
          <div>
            <button class="admission-student-select" type="button" data-action="select-admission-student" data-id="${student.id}">
              ${selectedAdmissionStudentId === student.id ? "Selected" : "Select"}
            </button>
          </div>
        </article>
      `;
    }).join("");

    admissionLetterEmptyState.hidden = students.length !== 0;

    const selectedStudent = students.find(function (student) { return student.id === selectedAdmissionStudentId; }) || null;
    renderAdmissionLetterDetail(selectedStudent);
  }

