  async function sendStudentIdCardWhatsapp(student) {
    if (!student) {
      return;
    }
    const normalizedStudent = normalizeStudentForPrint(student);
    const recipientPhone = normalizeSmsPhone(normalizedStudent.phone || normalizedStudent.fatherPhone || "");
    if (!recipientPhone) {
      alert("Student phone number not found.");
      return;
    }
    const baseText = interpolateTemplate(getSavedMessageTemplate("studentIdCard", getDefaultStudentIdCardTemplate()), {
      prefix: getGenderPrefix(normalizedStudent.gender),
      name: normalizedStudent.name || "-",
      Name: normalizedStudent.name || "-",
      roll: normalizedStudent.admissionNo || "-",
      class: normalizedStudent.className || "-",
      school: database.school.name || "School"
    });
    logWhatsappCommunication({
      recipientName: normalizedStudent.name || "-",
      recipientPhone: recipientPhone,
      message: baseText,
      source: "Student ID Card WhatsApp",
      recipientType: "student",
      campaignType: "id-card"
    });
  }

  async function sendStudentIdCardSms(student) {
    if (!student) {
      return;
    }
    const normalizedStudent = normalizeStudentForPrint(student);
    const recipientPhone = normalizeSmsPhone(normalizedStudent.phone || normalizedStudent.fatherPhone || "");
    if (!recipientPhone) {
      alert("Student phone number not found.");
      return;
    }
    const messageText = interpolateTemplate(getSavedMessageTemplate("studentIdCard", getDefaultStudentIdCardTemplate()), {
      prefix: getGenderPrefix(normalizedStudent.gender),
      name: normalizedStudent.name || "-",
      Name: normalizedStudent.name || "-",
      roll: normalizedStudent.admissionNo || "-",
      class: normalizedStudent.className || "-",
      school: database.school.name || "School"
    });
    const result = await sendSmsSmart({
      recipientName: normalizedStudent.name || "-",
      recipientPhone: recipientPhone,
      message: messageText,
      source: "Student ID Card SMS",
      recipientType: "student",
      campaignType: "id-card"
    });
    openAppMessageBox(result.success ? "Success" : "Error", result.success ? "Student ID card SMS sent successfully." : "Unable to send student ID card SMS. Check SMS gateway.", result.success ? "success" : "error");
  }

  function renderPrintBasicListTable() {
    const students = getPrintBasicListStudents();

    printBasicListTableBody.innerHTML = students.map(function (student, index) {
      return `
        <tr>
          <td>${index + 1}</td>
          <td>${student.admissionNo || "-"}</td>
          <td>${student.name || "-"}</td>
          <td>${student.fatherName || "-"}</td>
          <td>${student.className || "-"}</td>
          <td>${student.phone || "-"}</td>
          <td><span class="status-pill ${formatStatus(student.status)}">${student.status}</span></td>
        </tr>
      `;
    }).join("");

    printBasicListEmptyState.hidden = students.length !== 0;
  }

  function renderManageLoginTable() {
    const students = getManageLoginStudents();

    studentsManageLoginTableBody.innerHTML = students.map(function (student) {
      const loginInfo = getStudentLoginInfo(student);
      return `
        <tr>
          <td>${student.admissionNo || "-"}</td>
          <td>${student.name || "-"}</td>
          <td><input class="table-inline-input" type="text" value="${loginInfo.username}" data-login-field="username" data-id="${student.id}"></td>
          <td><input class="table-inline-input" type="text" value="${loginInfo.password}" data-login-field="password" data-id="${student.id}"></td>
          <td><span class="status-pill ${loginInfo.status === "Active" ? "active" : "inactive"}">${loginInfo.status}</span></td>
          <td><button class="table-action-btn" type="button" data-action="save-student-login" data-id="${student.id}">Save</button></td>
        </tr>
      `;
    }).join("");

    studentsManageLoginEmptyState.hidden = students.length !== 0;
  }

  function renderPromoteStudentsTable() {
    const students = getPromoteStudents();

    students.forEach(function (student) {
      if (typeof promoteSelectionState[student.id] === "undefined") {
        promoteSelectionState[student.id] = true;
      }
    });

    promoteStudentsTableBody.innerHTML = students.map(function (student) {
      const checked = promoteSelectionState[student.id] ? "checked" : "";
      return `
        <tr>
          <td><input class="promote-checkbox" type="checkbox" data-action="toggle-promote-selection" data-id="${student.id}" ${checked}></td>
          <td>${student.admissionNo || "-"}</td>
          <td>${student.name || "-"}</td>
          <td>${student.fatherName || "-"}</td>
          <td>${student.className || "-"}</td>
        </tr>
      `;
    }).join("");

    promoteStudentsEmptyState.hidden = students.length !== 0;
  }

  function printBasicList() {
    try {
      const students = getPrintBasicListStudents();
      if (students.length === 0) {
        return;
      }

      const classLabel = printBasicListClassFilter.value === "all" ? "All Classes" : printBasicListClassFilter.value;
      const profile = (database.generalSettings && database.generalSettings.instituteProfile) || {};
      const schoolName = profile.name || database.school.name || "School Name";
      const logo = String(profile.logo || "");
      const rows = students.map(function (student, index) {
        const normalizedStudent = normalizeStudentForPrint(student);
        return `<tr>
          <td>${index + 1}</td>
          <td>${escapePrintHtml(normalizedStudent.admissionNo || "-")}</td>
          <td>${escapePrintHtml(normalizedStudent.name || "-")}</td>
          <td>${escapePrintHtml(normalizedStudent.fatherName || "-")}</td>
          <td>${escapePrintHtml(normalizedStudent.className || "-")}</td>
          <td>${escapePrintHtml(normalizedStudent.phone || "-")}</td>
          <td>${escapePrintHtml(normalizedStudent.status || "-")}</td>
        </tr>`;
      }).join("");
      const printHtml = `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="utf-8">
        <title></title>
        <style>
          body { margin:0; font-family:"Segoe UI",Arial,sans-serif; color:#102542; background:#fff; }
          .wrap { padding:22px; }
          .head { text-align:center; margin-bottom:10px; }
          .head img { width:62px; height:62px; border-radius:12px; object-fit:cover; }
          .head h1 { margin:6px 0 2px; font-size:1.45rem; }
          .head p { margin:0; color:#4e678f; }
          .sub { text-align:center; margin:8px 0 12px; color:#5f7394; }
          table { width:100%; border-collapse:collapse; border:1px solid #000; }
          th, td { border:1px solid #000; padding:8px; text-align:left; background:#fff; }
          th { font-size:.78rem; text-transform:uppercase; }
          @media print { * { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }
        </style>
      </head>
      <body>
        <main class="wrap">
          <section class="head">
            ${logo ? `<img src="${escapePrintAttr(logo)}" alt="School logo">` : ""}
            <h1>${escapePrintHtml(schoolName)}</h1>
            <p>${escapePrintHtml(profile.slogan || "School Management System")}</p>
          </section>
          <p class="sub">Basic Student List | ${escapePrintHtml(classLabel)}</p>
          <table>
            <thead><tr><th>Sr. No</th><th>Roll Number</th><th>Name</th><th>Father Name</th><th>Class</th><th>Phone Number</th><th>Status</th></tr></thead>
            <tbody>${rows}</tbody>
          </table>
        </main>
        <script>
          window.addEventListener("load", function () {
            setTimeout(function () {
              window.print();
            }, 500);
          });
        </script>
      </body>
      </html>
      `;
      openPrintHtmlWindow(printHtml, "width=1150,height=900", "Please allow popups to print.");
    } catch (error) {
      console.error("Print basic list error:", error);
      alert("Print List abhi open nahi ho raha. Dobara try karein.");
    }
  }

  function saveStudentLoginCredentials(studentId) {
    const student = database.students.find(function (item) { return item.id === studentId; });
    if (!student) {
      return;
    }

    const usernameInput = studentsManageLoginTableBody.querySelector(`[data-login-field="username"][data-id="${studentId}"]`);
    const passwordInput = studentsManageLoginTableBody.querySelector(`[data-login-field="password"][data-id="${studentId}"]`);
    if (!usernameInput || !passwordInput) {
      return;
    }

    const username = usernameInput.value.trim();
    const password = passwordInput.value.trim();
    if (!username || !password) {
      return;
    }

    const existingIndex = database.users.findIndex(function (user) {
      return user.role === "student" && user.id === `LOGIN-${student.id}`;
    });

    const loginUser = {
      id: `LOGIN-${student.id}`,
      name: student.name,
      email: username,
      password: password,
      role: "student",
      phone: student.phone || "",
      active: student.status === "active"
    };

    if (existingIndex >= 0) {
      database.users[existingIndex] = loginUser;
      addActivity("Student login updated", `${student.name} login credentials were updated.`);
    } else {
      database.users.push(loginUser);
      addActivity("Student login created", `${student.name} login was created from manage login panel.`);
    }

    saveDatabase();
    refreshDatabase();
    renderDashboard();
    setStudentRoute("students-manage-login");
  }

  function getParentLoginId(student) {
    var parentPhone = student.fatherPhone || student.motherPhone || "";
    var normalizedPhone = parentPhone.replace(/[\s-]/g, "").toLowerCase();
    return normalizedPhone ? "PARENT-" + normalizedPhone : "PARENT-STU-" + student.id;
  }

  function renderParentLoginTable() {
    var searchValue = document.getElementById("parentLoginSearchInput");
    var query = searchValue ? searchValue.value.trim().toLowerCase() : "";
    var allStudents = database.students;
    if (query) {
      allStudents = allStudents.filter(function (s) {
        return (s.fatherName || "").toLowerCase().includes(query) ||
               (s.name || "").toLowerCase().includes(query);
      });
    }
    var tbody = document.getElementById("parentLoginTableBody");
    if (!tbody) return;
    tbody.innerHTML = allStudents.map(function (student) {
      var loginId = getParentLoginId(student);
      var existingUser = database.users.find(function (user) {
        return user.role === "parent" && user.id === loginId;
      });
      var isActive = existingUser && existingUser.active !== false;
      return [
        "<tr>",
        "<td>" + (student.fatherName || "-") + "</td>",
        "<td>" + (student.name || "-") + "</td>",
        "<td><input class=\"table-inline-input parent-login-cred-input\" type=\"text\" value=\"" + (existingUser ? existingUser.email : "") + "\" data-pl-field=\"username\" data-id=\"" + student.id + "\" disabled></td>",
        "<td><input class=\"table-inline-input parent-login-cred-input\" type=\"text\" value=\"" + (existingUser ? existingUser.password : "") + "\" data-pl-field=\"password\" data-id=\"" + student.id + "\" disabled></td>",
        "<td><label class=\"status-switch\"><input type=\"checkbox\" class=\"parent-login-toggle\" data-id=\"" + student.id + "\"" + (isActive ? " checked" : "") + " disabled><span>" + (isActive ? "Active" : "Inactive") + "</span></label></td>",
        "<td><button class=\"table-action-btn\" type=\"button\" data-action=\"edit-parent-login\" data-id=\"" + student.id + "\">Edit</button><button class=\"table-action-btn\" type=\"button\" data-action=\"save-parent-login\" data-id=\"" + student.id + "\" style=\"display:none\">Save</button></td>",
        "</tr>"
      ].join("");
    }).join("");
    var emptyState = document.getElementById("parentLoginEmptyState");
    if (emptyState) emptyState.hidden = allStudents.length !== 0;
  }

  function saveParentLoginCredentials(studentId) {
    var student = database.students.find(function (item) { return item.id === studentId; });
    if (!student) { openAppMessageBox("Error", "Student not found.", "error"); return; }
    var tbody = document.getElementById("parentLoginTableBody");
    if (!tbody) { openAppMessageBox("Error", "Table not found.", "error"); return; }
    var usernameInput = tbody.querySelector('[data-pl-field="username"][data-id="' + studentId + '"]');
    var passwordInput = tbody.querySelector('[data-pl-field="password"][data-id="' + studentId + '"]');
    if (!usernameInput || !passwordInput) { openAppMessageBox("Error", "Input fields not found.", "error"); return; }
    var username = usernameInput.value.trim();
    var password = passwordInput.value.trim();
    if (!username || !password) {
      openAppMessageBox("Error", "Username and password are required.", "error");
      return;
    }
    var loginId = getParentLoginId(student);
    var existingIndex = database.users.findIndex(function (user) {
      return user.role === "parent" && user.id === loginId;
    });
    var toggleCheckbox = tbody.querySelector('.parent-login-toggle[data-id="' + studentId + '"]');
    var isActive = toggleCheckbox ? toggleCheckbox.checked : true;
    var parentPhone = student.fatherPhone || student.motherPhone || "";
    var loginUser = {
      id: loginId,
      name: student.fatherName || student.motherName || student.name + "'s Parent",
      email: username,
      password: password,
      role: "parent",
      phone: parentPhone,
      active: isActive
    };
    var savedMsg;
    if (existingIndex >= 0) {
      database.users[existingIndex] = loginUser;
      addActivity("Parent login updated", student.fatherName + " login credentials were updated.");
      savedMsg = "Parent login updated successfully.";
    } else {
      database.users.push(loginUser);
      addActivity("Parent login created", student.fatherName + " received a new parent login.");
      savedMsg = "Parent login created successfully.";
    }
    saveDatabase();
    refreshDatabase();
    openAppMessageBox("Success", savedMsg, "success");
    renderDashboard();
    setStudentRoute("parents-manage-login");
  }

  function promoteSelectedStudents() {
    const targetClass = promoteTargetClassSelect.value;
    const filteredStudents = getPromoteStudents();
    const selectedStudents = filteredStudents.filter(function (student) {
      return promoteSelectionState[student.id];
    });

    if (!targetClass) {
      promoteStudentsMessage.textContent = "Please select target class.";
      promoteStudentsMessage.className = "form-message error";
      return;
    }

    if (selectedStudents.length === 0) {
      promoteStudentsMessage.textContent = "Please select at least one student.";
      promoteStudentsMessage.className = "form-message error";
      return;
    }

    selectedStudents.forEach(function (student) {
      student.className = targetClass;
    });

    addActivity("Students promoted", `${selectedStudents.length} student(s) promoted to ${targetClass}.`);
    saveDatabase();
    refreshDatabase();
    promoteStudentsMessage.textContent = `${selectedStudents.length} student(s) promoted successfully.`;
    promoteStudentsMessage.className = "form-message success";
    promoteSelectionState = {};
    renderDashboard();
    setStudentRoute("promote-students");
  }

  async function sendAdmissionConfirmationMessage() {
    if (!selectedAdmissionStudentId) {
      return;
    }
    const student = database.students.find(function (item) { return item.id === selectedAdmissionStudentId; }) || null;
    if (!student) {
      return;
    }
    const normalizedStudent = normalizeStudentForPrint(student);
    const recipientPhone = normalizeSmsPhone(
      normalizedStudent.phone ||
      normalizedStudent.fatherPhone ||
      normalizedStudent.studentPhone ||
      ""
    );
    if (!recipientPhone) {
      alert("Student phone number not found.");
      return;
    }
    const channelSelect = document.getElementById("admissionMessageChannelSelect");
    const channel = channelSelect ? channelSelect.value : chooseCommunicationChannel("Admission Confirmation");
    if (!channel) {
      return;
    }
    const templateText = getSavedMessageTemplate("admissionLetter", getDefaultAdmissionLetterTemplate());
    const loginInfo = getStudentLoginInfo(student);
    const messageText = interpolateTemplate(templateText, {
      prefix: getGenderPrefix(normalizedStudent.gender),
      name: normalizedStudent.name || "-",
      roll: normalizedStudent.admissionNo || "-",
      class: normalizedStudent.className || "-",
      section: normalizedStudent.section || "-",
      admissionDate: normalizedStudent.dateOfAdmission || "-",
      username: loginInfo.username || "-",
      password: loginInfo.password || "-",
      school: database.school.name || "School"
    });
    if (channel === "sms") {
      const result = await sendSmsSmart({
        recipientName: normalizedStudent.name || "-",
        recipientPhone: recipientPhone,
        message: messageText,
        source: "Admission Letter SMS",
        recipientType: "student",
        campaignType: "admission"
      });
      if (!result.success) {
        alert("Unable to send SMS. Please check SMS gateway connection.");
        return;
      }
      alert("Admission confirmation SMS sent successfully.");
      return;
    }
    const pdfHtml = printAdmissionLetter(true);
    const pdfResult = await saveCommunicationPdf(pdfHtml, `Admission-Letter-${normalizedStudent.name || normalizedStudent.admissionNo || "Student"}.pdf`);
    const whatsappText = pdfResult && pdfResult.success ? `${messageText}\nPDF: ${pdfResult.filePath}` : messageText;
    const logged = logWhatsappCommunication({
      recipientName: normalizedStudent.name || "-",
      recipientPhone: recipientPhone,
      message: whatsappText,
      source: "Admission Letter WhatsApp",
      recipientType: "student",
      campaignType: "admission"
    });
    if (logged) {
      alert("Admission confirmation WhatsApp message prepared and added to history.");
    }
  }

